# chunkexporter.py
# Chunk map exporter for Tiled Editor.
# Basically a custom CSV exporter.
# Go to Preferences > plugins, enable libpython.so.
# Then put this script in ~/.tiled.
from tiled import *
import os


class PSXChunk(Plugin):
    @classmethod
    def nameFilter(cls):
        return "PlayStation chunk proto map (*.cnk)"

    @classmethod
    def shortName(cls):
        return "cnk"

    @classmethod
    def write(cls, tileMap, fileName):
        for ilayer in range(tileMap.layerCount()):
            if isTileLayerAt(tileMap, ilayer):
                tileLayer = tileLayerAt(tileMap, ilayer)
                actual_filename = fileName
                if tileMap.layerCount() > 1:
                    actual_filename = f"{os.path.splitext(fileName)[0]}_{tileLayer.name().lower()}.cnk"
                with open(actual_filename, "w") as f:
                    width = tileLayer.width()
                    if width % 8 > 0:
                        width += 1
                    height = tileLayer.height()
                    if height % 8 > 0:
                        height += 1
                    for y in range(height):
                        tiles = []
                        for x in range(width):
                            if tileLayer.cellAt(x, y).tile() != None:
                                tiles.append(str(tileLayer.cellAt(x, y).tile().id()))
                            else:
                                tiles.append(str(-1))
                        line = ",".join(tiles)
                        print(line, file=f)
        return True

def tofixed(value: float, scale: int) -> int:
    return int(value * (1 << scale))


def tofixed12(value: float) -> int:
    return tofixed(value, 12)

# lvlexporter.py
# Level exporter for Tiled Editor.
# Go to Preferences > plugins, enable libpython.so.
# Then put this script in ~/.tiled.
from tiled import *
import json


class PSXPreLevel(Plugin):
    @classmethod
    def nameFilter(cls):
        return "PlayStation proto map (*.psxlvl)"

    @classmethod
    def shortName(cls):
        return "psxlvl"

    @classmethod
    def write(cls, tileMap, fileName):
        layer_count = 0
        for i in range(tileMap.layerCount()):
            if isTileLayerAt(tileMap, i):
                layer_count += 1

        filedata = {
            "num_layers": layer_count,
            "layer_data": [],
        }
        for i in range(tileMap.layerCount()):
            if isTileLayerAt(tileMap, i):
                layer = {}
                tileLayer = tileLayerAt(tileMap, i)
                assert tileLayer.width() < 256, f"max layer width is 255"
                assert tileLayer.height() < 32, f"max layer height is 31"
                layer["width"] = tileLayer.width()
                layer["height"] = tileLayer.height()
                layer["tiles"] = []
                for y in range(tileLayer.height()):
                    for x in range(tileLayer.width()):
                        tile = tileLayer.cellAt(x, y).tile()
                        layer["tiles"].append(tile.id() if tile else 0)
                filedata["layer_data"].append(layer)
        with open(fileName, "w") as f:
            print(json.dumps(filedata), file=f)
        return True

