/*
 * psxtypes.h - PlayStation 1 style types for asset tools
 * Big-endian binary output helpers
 */

#ifndef PSXTYPES_H
#define PSXTYPES_H

#include <stdint.h>
#include <stdio.h>

/* Fixed-width types */
typedef uint8_t  u8;
typedef int8_t   s8;
typedef uint16_t u16;
typedef int16_t  s16;
typedef uint32_t u32;
typedef int32_t  s32;

/* PSX angle type (20.12 fixed point, 0-4096 for 360 degrees) */
typedef s32 psx_angle_t;

/* Fixed point conversion */
#define FIXED12_SHIFT 12
#define to_fixed12(f) ((s32)((f) * (1 << FIXED12_SHIFT)))
#define from_fixed12(i) ((float)(i) / (1 << FIXED12_SHIFT))

/* Big-endian write helpers */
static inline void write_u8(FILE *f, u8 val) {
    fwrite(&val, 1, 1, f);
}

static inline void write_s8(FILE *f, s8 val) {
    fwrite(&val, 1, 1, f);
}

static inline void write_u16_be(FILE *f, u16 val) {
    u8 buf[2] = { (val >> 8) & 0xFF, val & 0xFF };
    fwrite(buf, 1, 2, f);
}

static inline void write_s16_be(FILE *f, s16 val) {
    write_u16_be(f, (u16)val);
}

static inline void write_u32_be(FILE *f, u32 val) {
    u8 buf[4] = { 
        (val >> 24) & 0xFF,
        (val >> 16) & 0xFF,
        (val >> 8) & 0xFF,
        val & 0xFF
    };
    fwrite(buf, 1, 4, f);
}

static inline void write_s32_be(FILE *f, s32 val) {
    write_u32_be(f, (u32)val);
}

/* Angle conversion: degrees to PSX angle (0-360 = 0-4096) */
static inline psx_angle_t degrees_to_psx_angle(float degrees) {
    float ratio = degrees / 360.0f;
    return (psx_angle_t)(ratio * 4096.0f);
}

/* Vector type matching PSX GTE format */
typedef struct {
    s32 vx, vy, vz;
} VECTOR;

static inline void write_vector_be(FILE *f, const VECTOR *v) {
    write_s32_be(f, v->vx);
    write_s32_be(f, v->vy);
    write_s32_be(f, v->vz);
}

#endif /* PSXTYPES_H */

/*
 * minilib.h - Minimal utility library for engine-psx tools
 * CSV, file I/O, string utilities
 */

#ifndef MINILIB_H
#define MINILIB_H

#include <stddef.h>
#include <stdbool.h>

/* Dynamic array (vector) helper - simplified version */
typedef struct {
    char *data;
    size_t len;
    size_t cap;
} StringBuilder;

void sb_init(StringBuilder *sb);
void sb_free(StringBuilder *sb);
void sb_append(StringBuilder *sb, const char *str);
void sb_append_char(StringBuilder *sb, char c);
char* sb_get(StringBuilder *sb);

/* File utilities */
char* read_file_text(const char *filename);
unsigned char* read_file_binary(const char *filename, size_t *size);

/* CSV parsing - simple version */
typedef struct {
    int *data;
    int rows;
    int cols;
} IntMatrix;

IntMatrix* csv_parse_int_matrix(const char *filename);
void csv_free_matrix(IntMatrix *mat);

/* Simple JSON-like path parsing for cJSON */
cJSON* cJSON_GetObjectPath(cJSON *root, const char *path);

/* Math utilities */
#define MIN(a,b) ((a)<(b)?(a):(b))
#define MAX(a,b) ((a)>(b)?(a):(b))
#define CLAMP(x,lo,hi) (MAX(lo,MIN(hi,x)))

/* Normalized vector */
void normalize_vector(float *v, int len);

#endif /* MINILIB_H */

/*
 * minilib.c - Implementation
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "minilib.h"

/* String Builder */
void sb_init(StringBuilder *sb) {
    sb->data = NULL;
    sb->len = 0;
    sb->cap = 0;
}

void sb_free(StringBuilder *sb) {
    free(sb->data);
    sb->data = NULL;
    sb->len = sb->cap = 0;
}

void sb_ensure_cap(StringBuilder *sb, size_t needed) {
    if (needed > sb->cap) {
        size_t new_cap = sb->cap ? sb->cap * 2 : 64;
        while (new_cap < needed) new_cap *= 2;
        sb->data = realloc(sb->data, new_cap);
        sb->cap = new_cap;
    }
}

void sb_append(StringBuilder *sb, const char *str) {
    size_t len = strlen(str);
    sb_ensure_cap(sb, sb->len + len + 1);
    memcpy(sb->data + sb->len, str, len);
    sb->len += len;
    sb->data[sb->len] = '\0';
}

void sb_append_char(StringBuilder *sb, char c) {
    sb_ensure_cap(sb, sb->len + 2);
    sb->data[sb->len] = c;
    sb->len++;
    sb->data[sb->len] = '\0';
}

char* sb_get(StringBuilder *sb) {
    return sb->data ? sb->data : "";
}

/* File utilities */
char* read_file_text(const char *filename) {
    FILE *f = fopen(filename, "rb");
    if (!f) return NULL;

    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);

    char *buf = malloc(size + 1);
    if (!buf) {
        fclose(f);
        return NULL;
    }

    fread(buf, 1, size, f);
    buf[size] = '\0';
    fclose(f);
    return buf;
}

unsigned char* read_file_binary(const char *filename, size_t *size) {
    FILE *f = fopen(filename, "rb");
    if (!f) return NULL;

    fseek(f, 0, SEEK_END);
    *size = ftell(f);
    fseek(f, 0, SEEK_SET);

    unsigned char *buf = malloc(*size);
    if (!buf) {
        fclose(f);
        return NULL;
    }

    fread(buf, 1, *size, f);
    fclose(f);
    return buf;
}

/* CSV parsing - simple version */
IntMatrix* csv_parse_int_matrix(const char *filename) {
    char *text = read_file_text(filename);
    if (!text) return NULL;

    IntMatrix *mat = calloc(1, sizeof(IntMatrix));

    // First pass: count rows and columns
    int cols = 0, max_cols = 0;
    int rows = 1;  // At least one row if file not empty
    bool in_value = false;

    for (char *p = text; *p; p++) {
        if (*p == ',') {
            if (in_value) cols++;
            in_value = false;
        } else if (*p == '\n') {
            if (in_value) cols++;
            if (cols > max_cols) max_cols = cols;
            cols = 0;
            in_value = false;
            rows++;
        } else if (*p != '\r' && *p != ' ' && *p != '\t') {
            in_value = true;
        }
    }
    if (in_value) cols++;
    if (cols > max_cols) max_cols = cols;

    // Adjust for trailing newline
    int len = strlen(text);
    if (len > 0 && (text[len-1] == '\n' || text[len-1] == '\r')) rows--;

    mat->rows = rows;
    mat->cols = max_cols;
    mat->data = malloc(rows * max_cols * sizeof(int));
    memset(mat->data, -1, rows * max_cols * sizeof(int));

    // Second pass: parse values
    int row = 0, col = 0;
    char *p = text;
    while (*p && row < rows) {
        // Skip whitespace
        while (*p == ' ' || *p == '\t') p++;

        if (*p == '\n' || *p == '\r') {
            row++;
            col = 0;
            p++;
            if (*p == '\n' || *p == '\r') p++;
            continue;
        }

        if (*p == ',') {
            col++;
            p++;
            continue;
        }

        // Parse number
        char *end;
        int val = strtol(p, &end, 10);
        if (end != p) {
            if (row < rows && col < max_cols) {
                mat->data[row * max_cols + col] = val;
            }
            p = end;
            col++;
        } else {
            p++;
        }
    }

    free(text);
    return mat;
}

void csv_free_matrix(IntMatrix *mat) {
    if (mat) {
        free(mat->data);
        free(mat);
    }
}

/* Normalize vector (float) */
void normalize_vector(float *v, int len) {
    float sum = 0;
    for (int i = 0; i < len; i++) sum += v[i] * v[i];
    float norm = sqrt(sum);
    if (norm > 0) {
        for (int i = 0; i < len; i++) v[i] /= norm;
    }
}

/* cJSON path helper - forward declaration, implementation in cooklvl */
#include "cJSON.h"

cJSON* cJSON_GetObjectPath(cJSON *root, const char *path) {
    cJSON *current = root;
    char *buf = strdup(path);
    char *token = strtok(buf, ".");

    while (token && current) {
        current = cJSON_GetObjectItemCaseSensitive(current, token);
        token = strtok(NULL, ".");
    }

    free(buf);
    return current;
}

/*
 * cooklvl.c - Convert level JSON to binary PSX format
 * Replaces cooklvl.py
 * 
 * Binary layout:
 * - num_layers (u8)
 * - _unused (u8)
 * Per layer:
 *   - width (u8)
 *   - height (u8)
 *   - tiles[] (u16 BE)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "cJSON.h"
#include "psxtypes.h"

#define MAX_LAYERS 3
#define MAX_WIDTH 256
#define MAX_HEIGHT 256

typedef struct {
    u8 width;
    u8 height;
    u16 *tiles;
} LayerData;

typedef struct {
    u8 num_layers;
    LayerData layers[MAX_LAYERS];
} LevelData;

void print_usage(const char *prog) {
    fprintf(stderr, "Usage: %s <input.json> <output.LVL>\n", prog);
}

int parse_level(const char *filename, LevelData *level) {
    FILE *f = fopen(filename, "r");
    if (!f) {
        fprintf(stderr, "Error: cannot open %s\n", filename);
        return -1;
    }

    // Read entire file
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = malloc(size + 1);
    fread(buf, 1, size, f);
    buf[size] = '\0';
    fclose(f);

    cJSON *root = cJSON_Parse(buf);
    free(buf);

    if (!root) {
        fprintf(stderr, "Error: JSON parse failed: %s\n", cJSON_GetErrorPtr());
        return -1;
    }

    // Get num_layers
    cJSON *num_layers = cJSON_GetObjectItem(root, "num_layers");
    if (!cJSON_IsNumber(num_layers)) {
        fprintf(stderr, "Error: missing or invalid num_layers\n");
        cJSON_Delete(root);
        return -1;
    }
    level->num_layers = (u8)num_layers->valueint;
    printf("Number of level layers: %d\n", level->num_layers);

    if (level->num_layers > MAX_LAYERS) {
        fprintf(stderr, "Error: too many layers (max %d)\n", MAX_LAYERS);
        cJSON_Delete(root);
        return -1;
    }

    // Parse layer_data
    cJSON *layer_data = cJSON_GetObjectItem(root, "layer_data");
    if (!cJSON_IsArray(layer_data)) {
        fprintf(stderr, "Error: missing layer_data array\n");
        cJSON_Delete(root);
        return -1;
    }

    int layer_count = cJSON_GetArraySize(layer_data);
    for (int i = 0; i < layer_count && i < MAX_LAYERS; i++) {
        cJSON *layer = cJSON_GetArrayItem(layer_data, i);
        cJSON *width = cJSON_GetObjectItem(layer, "width");
        cJSON *height = cJSON_GetObjectItem(layer, "height");
        cJSON *tiles = cJSON_GetObjectItem(layer, "tiles");

        if (!cJSON_IsNumber(width) || !cJSON_IsNumber(height) || !cJSON_IsArray(tiles)) {
            fprintf(stderr, "Error: invalid layer %d format\n", i);
            continue;
        }

        level->layers[i].width = (u8)width->valueint;
        level->layers[i].height = (u8)height->valueint;

        if (level->layers[i].width >= MAX_WIDTH || level->layers[i].height >= MAX_HEIGHT) {
            fprintf(stderr, "Error: layer %d exceeds max dimensions\n", i);
            cJSON_Delete(root);
            return -1;
        }

        int tile_count = cJSON_GetArraySize(tiles);
        level->layers[i].tiles = malloc(tile_count * sizeof(u16));

        for (int j = 0; j < tile_count; j++) {
            cJSON *tile = cJSON_GetArrayItem(tiles, j);
            level->layers[i].tiles[j] = (u16)tile->valueint;
        }
    }

    cJSON_Delete(root);
    return 0;
}

int write_level(const char *filename, const LevelData *level) {
    FILE *f = fopen(filename, "wb");
    if (!f) {
        fprintf(stderr, "Error: cannot create %s\n", filename);
        return -1;
    }

    // Write header
    write_u8(f, level->num_layers);
    write_u8(f, 0); // _unused

    // Write each layer
    for (int i = 0; i < level->num_layers; i++) {
        write_u8(f, level->layers[i].width);
        write_u8(f, level->layers[i].height);

        int tile_count = level->layers[i].width * level->layers[i].height;
        for (int j = 0; j < tile_count; j++) {
            write_u16_be(f, level->layers[i].tiles[j]);
        }

        printf("Layer %d: %dx%d = %d tiles\n", i, 
               level->layers[i].width, level->layers[i].height, tile_count);
    }

    fclose(f);
    return 0;
}

void free_level(LevelData *level) {
    for (int i = 0; i < MAX_LAYERS; i++) {
        free(level->layers[i].tiles);
        level->layers[i].tiles = NULL;
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        print_usage(argv[0]);
        return 1;
    }

    const char *input = argv[1];
    const char *output = argv[2];

    LevelData level = {0};

    if (parse_level(input, &level) != 0) {
        return 1;
    }

    if (write_level(output, &level) != 0) {
        free_level(&level);
        return 1;
    }

    free_level(&level);
    printf("Successfully wrote %s\n", output);

    return 0;
}

/*
 * buildprl.c - Convert parallax TOML to binary PRL format
 * Replaces buildprl.py
 * 
 * Output: PRL.PRL in same directory as input TOML
 * 
 * Binary layout:
 * - num_strips (u8)
 * For each strip:
 *   - u0 (u8), v0 (u8)
 *   - width (u16 BE), height (u16 BE)
 *   - bg_index (u8)
 *   - single (u8)
 *   - scrollx (s32 BE - 20.12 fixed)
 *   - speedx (s32 BE - 20.12 fixed)
 *   - y0 (s16 BE)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.hu003e
#include <libgen.h>
#include "toml.h"
#include "psxtypes.h"

#define MAX_STRIPS 256

typedef struct {
    u8 u0;
    u8 v0;
    u16 width;
    u16 height;
    u8 bg_index;
    u8 single;
    s32 scrollx;  // 20.12 fixed point
    s32 speedx;   // 20.12 fixed point
    s16 y0;
} ParallaxStrip;

typedef struct {
    int num_strips;
    ParallaxStrip strips[MAX_STRIPS];
} ParallaxData;

static inline s32 float_to_fixed12(float f) {
    return (s32)(f * 4096.0f);
}

void print_usage(const char *prog) {
    fprintf(stderr, "Usage: %s <parallax.toml>\n", prog);
    fprintf(stderr, "Output: PRL.PRL in same directory as input\n");
}

const char* get_output_path(const char *input_path) {
    static char output_path[1024];
    char *copy = strdup(input_path);
    char *dir = dirname(copy);

    if (strlen(dir) > 0) {
        snprintf(output_path, sizeof(output_path), "%s/PRL.PRL", dir);
    } else {
        snprintf(output_path, sizeof(output_path), "PRL.PRL");
    }

    free(copy);
    return output_path;
}

int parse_parallax(const char *filename, ParallaxData *prl) {
    FILE *f = fopen(filename, "r");
    if (!f) {
        fprintf(stderr, "Error: cannot open %s\n", filename);
        return -1;
    }

    // Read entire file
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = malloc(size + 1);
    fread(buf, 1, size, f);
    buf[size] = '\0';
    fclose(f);

    char errbuf[256];
    toml_table_t *root = toml_parse(buf, errbuf, sizeof(errbuf));
    free(buf);

    if (!root) {
        fprintf(stderr, "Error: TOML parse failed: %s\n", errbuf);
        return -1;
    }

    // Iterate through all keys in root table (each is a strip)
    int num_strips = 0;
    for (int i = 0; ; i++) {
        const char *key = toml_key_in(root, i);
        if (!key) break;

        toml_table_t *strip = toml_table_in(root, key);
        if (!strip) continue;

        if (num_strips >= MAX_STRIPS) {
            fprintf(stderr, "Warning: max strips (%d) reached, ignoring rest\n", MAX_STRIPS);
            break;
        }

        ParallaxStrip *s = &prl->strips[num_strips];
        memset(s, 0, sizeof(ParallaxStrip));

        // Read values with defaults
        toml_datum_t u0 = toml_int_in(strip, "u0");
        toml_datum_t v0 = toml_int_in(strip, "v0");
        toml_datum_t width = toml_int_in(strip, "width");
        toml_datum_t height = toml_int_in(strip, "height");
        toml_datum_t y0 = toml_int_in(strip, "y0");

        // Optional floats
        toml_datum_t scrollx = toml_double_in(strip, "scrollx");
        toml_datum_t speedx = toml_double_in(strip, "speedx");

        // Optional bool
        toml_datum_t single = toml_bool_in(strip, "single");

        s->u0 = u0.ok ? (u8)u0.u.i : 0;
        s->v0 = v0.ok ? (u8)v0.u.i : 0;
        s->width = width.ok ? (u16)width.u.i : 0;
        s->height = height.ok ? (u16)height.u.i : 0;
        s->y0 = y0.ok ? (s16)y0.u.i : 0;

        // Calculate bg_index and actual v0
        s->bg_index = (s->v0 >= 256) ? (s->v0 / 256) : 0;
        s->v0 = s->v0 % 256;

        s->scrollx = scrollx.ok ? float_to_fixed12((float)scrollx.u.d) : 0;
        s->speedx = speedx.ok ? float_to_fixed12((float)speedx.u.d) : 0;
        s->single = single.ok ? (single.u.b ? 1 : 0) : 0;

        printf("Strip %s: u0=%d v0=%d (%d:%d) %dx%d y0=%d\n", 
               key, s->u0, s->v0, s->bg_index, s->v0, 
               s->width, s->height, s->y0);

        num_strips++;
    }

    prl->num_strips = num_strips;
    toml_free(root);

    printf("Total strips: %d\n", num_strips);
    return 0;
}

int write_parallax(const char *filename, const ParallaxData *prl) {
    FILE *f = fopen(filename, "wb");
    if (!f) {
        fprintf(stderr, "Error: cannot create %s\n", filename);
        return -1;
    }

    // Write number of strips
    write_u8(f, (u8)prl->num_strips);

    // Write each strip
    for (int i = 0; i < prl->num_strips; i++) {
        const ParallaxStrip *s = &prl->strips[i];
        write_u8(f, s->u0);
        write_u8(f, s->v0);
        write_u16_be(f, s->width);
        write_u16_be(f, s->height);
        write_u8(f, s->bg_index);
        write_u8(f, s->single);
        write_s32_be(f, s->scrollx);
        write_s32_be(f, s->speedx);
        write_s16_be(f, s->y0);
    }

    fclose(f);
    printf("Created %s\n", filename);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        print_usage(argv[0]);
        return 1;
    }

    const char *input = argv[1];
    const char *output = get_output_path(input);

    ParallaxData prl = {0};

    if (parse_parallax(input, &prl) != 0) {
        return 1;
    }

    if (write_parallax(output, &prl) != 0) {
        return 1;
    }

    return 0;
}

/*
 * framepacker.c - Pack Aseprite JSON frames to binary CHARA format
 * Replaces framepacker.py
 * 
 * Binary layout:
 * - sprite_width (u16 BE)
 * - sprite_height (u16 BE)
 * - num_frames (u16 BE)
 * - num_animations (u16 BE)
 * Per frame:
 *   - x (u8), y (u8)
 *   - cols (u8), rows (u8)
 *   - width (u16 BE), height (u16 BE)
 *   - tiles[] (u16 BE * cols * rows)
 * Per animation:
 *   - name[16] (padded with 0s)
 *   - start (u8), end (u8)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include "cJSON.h"
#include "psxtypes.h"

#define MAX_NAME_LEN 16
#define MAX_TILES 2048

typedef struct {
    u8 x, y;
    u8 cols, rows;
    u16 width, height;
    u16 *tiles;
    int num_tiles;
} FrameData;

typedef struct {
    char name[MAX_NAME_LEN + 1];
    u8 start;
    u8 end;
} AnimationData;

typedef struct {
    u16 sprite_width;
    u16 sprite_height;
    int num_frames;
    FrameData frames[MAX_TILES];
    int num_animations;
    AnimationData animations[256];
} SpriteData;

void print_usage(const char *prog) {
    fprintf(stderr, "Usage: %s [--tilemap] <input.json> <output.CHAR>\n", prog);
    fprintf(stderr, "  --tilemap  Output level tilemap format instead of sprite\n");
}

// Parse name: uppercase, replace spaces with nothing, pad to 16 chars
void format_name(const char *input, char *output) {
    int j = 0;
    for (int i = 0; input[i] && j < MAX_NAME_LEN; i++) {
        if (input[i] != ' ') {
            output[j++] = (char)toupper((unsigned char)input[i]);
        }
    }
    while (j <= MAX_NAME_LEN) output[j++] = '\0';
}

int compare_frames(const void *a, const void *b) {
    cJSON *fa = *(cJSON **)a;
    cJSON *fb = *(cJSON **)b;
    cJSON *frame_a = cJSON_GetObjectItem(fa, "frame");
    cJSON *frame_b = cJSON_GetObjectItem(fb, "frame");
    int fa_i = frame_a ? frame_a->valueint : 0;
    int fb_i = frame_b ? frame_b->valueint : 0;
    return fa_i - fb_i;
}

int parse_sprite(const char *filename, SpriteData *sprite) {
    FILE *f = fopen(filename, "r");
    if (!f) {
        fprintf(stderr, "Error: cannot open %s\n", filename);
        return -1;
    }

    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = malloc(size + 1);
    fread(buf, 1, size, f);
    buf[size] = '\0';
    fclose(f);

    cJSON *root = cJSON_Parse(buf);
    free(buf);

    if (!root) {
        fprintf(stderr, "Error: JSON parse failed: %s\n", cJSON_GetErrorPtr());
        return -1;
    }

    // Parse basic info
    cJSON *width = cJSON_GetObjectItem(root, "width");
    cJSON *height = cJSON_GetObjectItem(root, "height");
    sprite->sprite_width = width ? (u16)width->valueint : 0;
    sprite->sprite_height = height ? (u16)height->valueint : 0;

    // Parse layers -> cels -> frames
    cJSON *layers = cJSON_GetObjectItem(root, "layers");
    if (!cJSON_IsArray(layers) || cJSON_GetArraySize(layers) == 0) {
        fprintf(stderr, "Error: no layers found\n");
        cJSON_Delete(root);
        return -1;
    }

    cJSON *layer0 = cJSON_GetArrayItem(layers, 0);
    cJSON *cels = cJSON_GetObjectItem(layer0, "cels");
    if (!cJSON_IsArray(cels)) {
        fprintf(stderr, "Error: no cels found\n");
        cJSON_Delete(root);
        return -1;
    }

    // Sort cels by frame number
    int num_cels = cJSON_GetArraySize(cels);
    cJSON **cel_array = malloc(num_cels * sizeof(cJSON *));
    for (int i = 0; i < num_cels; i++) {
        cel_array[i] = cJSON_GetArrayItem(cels, i);
    }
    qsort(cel_array, num_cels, sizeof(cJSON *), compare_frames);

    // Parse frames
    sprite->num_frames = num_cels;
    for (int i = 0; i < num_cels; i++) {
        cJSON *cel = cel_array[i];
        cJSON *tilemap = cJSON_GetObjectItem(cel, "tilemap");
        cJSON *bounds = cJSON_GetObjectItem(cel, "bounds");

        FrameData *frame = &sprite->frames[i];
        frame->x = (u8)cJSON_GetObjectItem(bounds, "x")->valueint;
        frame->y = (u8)cJSON_GetObjectItem(bounds, "y")->valueint;
        frame->cols = (u8)cJSON_GetObjectItem(tilemap, "width")->valueint;
        frame->rows = (u8)cJSON_GetObjectItem(tilemap, "height")->valueint;
        frame->width = (u16)cJSON_GetObjectItem(bounds, "width")->valueint;
        frame->height = (u16)cJSON_GetObjectItem(bounds, "height")->valueint;

        cJSON *tiles = cJSON_GetObjectItem(tilemap, "tiles");
        frame->num_tiles = cJSON_GetArraySize(tiles);
        frame->tiles = malloc(frame->num_tiles * sizeof(u16));

        for (int j = 0; j < frame->num_tiles; j++) {
            cJSON *t = cJSON_GetArrayItem(tiles, j);
            frame->tiles[j] = (u16)t->valueint;
        }
    }
    free(cel_array);

    // Parse animation tags
    cJSON *tags = cJSON_GetObjectItem(root, "tags");
    if (cJSON_IsArray(tags)) {
        int num_tags = cJSON_GetArraySize(tags);
        sprite->num_animations = num_tags;

        for (int i = 0; i < num_tags; i++) {
            cJSON *tag = cJSON_GetArrayItem(tags, i);
            cJSON *name = cJSON_GetObjectItem(tag, "name");
            cJSON *from = cJSON_GetObjectItem(tag, "from");
            cJSON *to = cJSON_GetObjectItem(tag, "to");

            format_name(name->valuestring, sprite->animations[i].name);
            sprite->animations[i].start = (u8)from->valueint;
            sprite->animations[i].end = (u8)to->valueint;
        }
    }

    cJSON_Delete(root);
    return 0;
}

void free_sprite(SpriteData *sprite) {
    for (int i = 0; i < sprite->num_frames; i++) {
        free(sprite->frames[i].tiles);
    }
}

int write_binary_sprite(const char *filename, const SpriteData *sprite) {
    FILE *f = fopen(filename, "wb");
    if (!f) {
        fprintf(stderr, "Error: cannot create %s\n", filename);
        return -1;
    }

    // Header
    write_u16_be(f, sprite->sprite_width);
    write_u16_be(f, sprite->sprite_height);
    write_u16_be(f, (u16)sprite->num_frames);
    write_u16_be(f, (u16)sprite->num_animations);

    // Frames
    for (int i = 0; i < sprite->num_frames; i++) {
        const FrameData *frame = &sprite->frames[i];
        write_u8(f, frame->x);
        write_u8(f, frame->y);
        write_u8(f, frame->cols);
        write_u8(f, frame->rows);
        write_u16_be(f, frame->width);
        write_u16_be(f, frame->height);

        for (int j = 0; j < frame->num_tiles; j++) {
            write_u16_be(f, frame->tiles[j]);
        }
    }

    // Animations
    for (int i = 0; i < sprite->num_animations; i++) {
        const AnimationData *anim = &sprite->animations[i];
        for (int j = 0; j < MAX_NAME_LEN; j++) {
            u8 c = (u8)((j < (int)strlen(anim->name) && anim->name[j]) ? anim->name[j] : 0);
            write_u8(f, c);
        }
        write_u8(f, anim->start);
        write_u8(f, anim->end);
    }

    fclose(f);
    return 0;
}

int write_binary_level(const char *filename, const SpriteData *sprite) {
    FILE *f = fopen(filename, "wb");
    if (!f) {
        fprintf(stderr, "Error: cannot create %s\n", filename);
        return -1;
    }

    // Simpler format for levels
    write_u16_be(f, sprite->sprite_width);
    write_u16_be(f, (u16)sprite->num_frames);

    if (sprite->num_frames > 0) {
        write_u16_be(f, sprite->frames[0].cols);

        // Write all tiles from all frames
        for (int i = 0; i < sprite->num_frames; i++) {
            const FrameData *frame = &sprite->frames[i];
            for (int j = 0; j < frame->num_tiles; j++) {
                write_u16_be(f, frame->tiles[j]);
            }
        }
    } else {
        write_u16_be(f, 0);
    }

    fclose(f);
    return 0;
}

int main(int argc, char *argv[]) {
    const char *input = NULL;
    const char *output = NULL;
    int is_level = 0;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--tilemap") == 0) {
            is_level = 1;
        } else if (!input) {
            input = argv[i];
        } else if (!output) {
            output = argv[i];
        }
    }

    if (!input || !output) {
        print_usage(argv[0]);
        return 1;
    }

    SpriteData sprite = {0};

    if (parse_sprite(input, &sprite) != 0) {
        return 1;
    }

    int ret;
    if (is_level) {
        ret = write_binary_level(output, &sprite);
    } else {
        ret = write_binary_sprite(output, &sprite);
    }

    free_sprite(&sprite);

    if (ret != 0) {
        return 1;
    }

    printf("Successfully created %s\n", output);
    return 0;
}

/*
 * chunkgen.c - Convert 128x128 chunks from CSV to MAP binary format
 * Replaces chunkgen.py
 * 
 * Binary layout:
 * - tile_width (u16 BE) - always 128
 * - num_tiles (u16 BE) - grid_width * grid_height
 * - frame_dim (u16 BE) - always 8
 * - For each chunk:
 *   - For each of 8x8 tiles:
 *     - tile_index (u16 BE)
 *     - props (u8) - 0=solid, 1=oneway, 2=nocol, 4=front
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include "psxtypes.h"

#define CHUNK_SIZE 8
#define TILE_WIDTH 128

// Layer type enum
enum LayerType {
    LAYER_SOLID = 0,
    LAYER_ONEWAY = 1,
    LAYER_NOCOL = 2,
    LAYER_FRONT = 3,
    MAX_LAYERS = 4
};

// Simple CSV matrix
typedef struct {
    int *data;
    int rows;
    int cols;
} Matrix;

void matrix_free(Matrix *m) {
    if (m) {
        free(m->data);
        m->data = NULL;
        m->rows = m->cols = 0;
    }
}

// Round up dimension to multiple of 8
int round_up_8(int d) {
    if (d % 8 > 0) {
        return d + (8 - (d % 8));
    }
    return d;
}

// Get chunk at position
void get_chunk(const Matrix *m, int cx, int cy, int *out) {
    int startx = cx * CHUNK_SIZE;
    int starty = cy * CHUNK_SIZE;

    for (int y = 0; y < CHUNK_SIZE; y++) {
        for (int x = 0; x < CHUNK_SIZE; x++) {
            int row = starty + y;
            int col = startx + x;
            int idx = y * CHUNK_SIZE + x;

            if (row < m->rows && col < m->cols) {
                out[idx] = m->data[row * m->cols + col];
            } else {
                out[idx] = -1;  // Empty
            }
        }
    }
}

// Parse CSV file
Matrix* csv_load(const char *filename) {
    FILE *f = fopen(filename, "r");
    if (!f) return NULL;

    Matrix *m = calloc(1, sizeof(Matrix));

    // First pass: count rows and max columns
    char line[16384];
    int rows = 0;
    int max_cols = 0;

    while (fgets(line, sizeof(line), f)) {
        int cols = 0;
        char *p = line;
        while (*p) {
            // Skip whitespace
            while (*p == ' ' || *p == '\t' || *p == '\r') p++;
            if (*p == '\n' || *p == '\0') break;

            // Parse number
            if (*p == '-') {
                p++; // Skip minus
                while (isdigit(*p) p++;
                cols++;
            } else if (isdigit(*p)) {
                while (isdigit(*p)) p++;
                cols++;
            } else if (*p == ',') {
                p++;
            } else {
                p++;
            }
        }
        if (cols > 0) {
            rows++;
            if (cols > max_cols) max_cols = cols;
        }
    }

    // Round up dimensions
    int final_cols = round_up_8(max_cols);
    int final_rows = round_up_8(rows);

    // Allocate and init with -1
    m->data = malloc(final_rows * final_cols * sizeof(int));
    for (int i = 0; i < final_rows * final_cols; i++) {
        m->data[i] = -1;
    }
    m->rows = final_rows;
    m->cols = final_cols;

    // Second pass: fill data
    rewind(f);
    int row = 0;

    while (fgets(line, sizeof(line), f) && row < final_rows) {
        int col = 0;
        char *p = line;

        while (*p && col < final_cols) {
            // Skip whitespace
            while (*p == ' ' || *p == '\t' || *p == '\r') p++;
            if (*p == '\n' || *p == '\0') break;
            if (*p == ',') {
                p++;
                continue;
            }

            // Parse number
            char *end;
            long val = strtol(p, &end, 10);
            if (end != p) {
                m->data[row * final_cols + col] = (int)val;
                col++;
                p = end;
            } else {
                p++;
            }
        }
        row++;
    }

    fclose(f);
    return m;
}

// Get grid dimensions
void get_grid_size(const Matrix *m, int *grid_w, int *grid_h) {
    *grid_w = m->cols / CHUNK_SIZE;
    *grid_h = m->rows / CHUNK_SIZE;
}

// Export binary
void export_binary(FILE *f, const Matrix *layers[MAX_LAYERS]) {
    const Matrix *solid = layers[LAYER_SOLID];
    int grid_w, grid_h;
    get_grid_size(solid, &grid_w, &grid_h);
    int num_chunks = grid_w * grid_h;

    // Header
    write_u16_be(f, TILE_WIDTH);
    write_u16_be(f, (u16)num_chunks);
    write_u16_be(f, CHUNK_SIZE);

    printf("Grid: %dx%d = %d chunks\n", grid_w, grid_h, num_chunks);

    // For each chunk
    for (int cy = 0; cy < grid_h; cy++) {
        for (int cx = 0; cx < grid_w; cx++) {
            int solid_chunk[CHUNK_SIZE * CHUNK_SIZE];
            int oneway_chunk[CHUNK_SIZE * CHUNK_SIZE] = {0};
            int nocol_chunk[CHUNK_SIZE * CHUNK_SIZE] = {0};
            int front_chunk[CHUNK_SIZE * CHUNK_SIZE] = {0};

            get_chunk(solid, cx, cy, solid_chunk);

            if (layers[LAYER_ONEWAY]) {
                get_chunk(layers[LAYER_ONEWAY], cx, cy, oneway_chunk);
            }
            if (layers[LAYER_NOCOL]) {
                get_chunk(layers[LAYER_NOCOL], cx, cy, nocol_chunk);
            }
            if (layers[LAYER_FRONT]) {
                get_chunk(layers[LAYER_FRONT], cx, cy, front_chunk);
            }

            // For each tile in chunk (row-major)
            for (int py = 0; py < CHUNK_SIZE; py++) {
                for (int px = 0; px < CHUNK_SIZE; px++) {
                    int idx = py * CHUNK_SIZE + px;
                    int tile_index = solid_chunk[idx];
                    u8 props = 0;

                    // Check alternative layers if solid is empty
                    if (tile_index <= 0 && layers[LAYER_ONEWAY] && oneway_chunk[idx] > 0) {
                        tile_index = oneway_chunk[idx];
                        props = 1;
                    }
                    if (tile_index <= 0 && layers[LAYER_NOCOL] && nocol_chunk[idx] > 0) {
                        tile_index = nocol_chunk[idx];
                        props = 2;
                    }
                    if (tile_index <= 0 && layers[LAYER_FRONT] && front_chunk[idx] > 0) {
                        tile_index = front_chunk[idx];
                        props = 4;
                    }

                    write_u16_be(f, (u16)(tile_index > 0 ? tile_index : 0));
                    write_u8(f, props);
                }
            }
        }
    }
}

void print_usage(const char *prog) {
    fprintf(stderr, "Usage: %s <input> <output.MAP>\n", prog);
    fprintf(stderr, "  input: either a single .cnk file or base path\n");
    fprintf(stderr, "         (will look for _solid.cnk, _oneway.cnk, etc.)\n");
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        print_usage(argv[0]);
        return 1;
    }

    const char *input = argv[1];
    const char *output = argv[2];

    Matrix *layers[MAX_LAYERS] = {0};

    // Check if single file or base path
    if (strstr(input, ".cnk")) {
        // Single mode
        layers[LAYER_SOLID] = csv_load(input);
        if (!layers[LAYER_SOLID]) {
            fprintf(stderr, "Error: cannot load %s\n", input);
            return 1;
        }
        printf("Loaded %s: %dx%d\n", input, layers[LAYER_SOLID]->cols, layers[LAYER_SOLID]->rows);
    } else {
        // Multi-layer mode
        char path[1024];

        // Solid (required)
        snprintf(path, sizeof(path), "%s_solid.cnk", input);
        layers[LAYER_SOLID] = csv_load(path);
        if (!layers[LAYER_SOLID]) {
            fprintf(stderr, "Error: cannot load %s\n", path);
            return 1;
        }
        printf("Loaded %s: %dx%d\n", path, layers[LAYER_SOLID]->cols, layers[LAYER_SOLID]->rows);

        // Optional layers
        snprintf(path, sizeof(path), "%s_oneway.cnk", input);
        if (FILE *test = fopen(path, "r")) {
            fclose(test);
            layers[LAYER_ONEWAY] = csv_load(path);
            if (layers[LAYER_ONEWAY]) {
                printf("Loaded %s: %dx%d\n", path, layers[LAYER_ONEWAY]->cols, layers[LAYER_ONEWAY]->rows);
            }
        }

        snprintf(path, sizeof(path), "%s_none.cnk", input);
        if (FILE *test = fopen(path, "r")) {
            fclose(test);
            layers[LAYER_NOCOL] = csv_load(path);
            if (layers[LAYER_NOCOL]) {
                printf("Loaded %s: %dx%d\n", path, layers[LAYER_NOCOL]->cols, layers[LAYER_NOCOL]->rows);
            }
        }

        snprintf(path, sizeof(path), "%s_front.cnk", input);
        if (FILE *test = fopen(path, "r")) {
            fclose(test);
            layers[LAYER_FRONT] = csv_load(path);
            if (layers[LAYER_FRONT]) {
                printf("Loaded %s: %dx%d\n", path, layers[LAYER_FRONT]->cols, layers[LAYER_FRONT]->rows);
            }
        }
    }

    FILE *f = fopen(output, "wb");
    if (!f) {
        fprintf(stderr, "Error: cannot create %s\n", output);
        goto cleanup;
    }

    export_binary(f, layers);
    fclose(f);

    printf("Successfully wrote %s\n", output);

cleanup:
    for (int i = 0; i < MAX_LAYERS; i++) {
        matrix_free(layers[i]);
    }

    return 0;
}

/*
 * cJSON.h - Minimal version of cJSON (header only subset)
 * For full version, see: https://github.com/DaveGamble/cJSON
 */

#ifndef CJSON_H
#define CJSON_H

#include <stddef.h>

/* cJSON Types */
typedef struct cJSON {
    struct cJSON *next;
    struct cJSON *prev;
    struct cJSON *child;
    int type;
    char *valuestring;
    int valueint;
    double valuedouble;
    char *string;
} cJSON;

#define cJSON_Invalid  (0)
#define cJSON_False    (1 << 0)
#define cJSON_True     (1 << 1)
#define cJSON_NULL     (1 << 2)
#define cJSON_Number   (1 << 3)
#define cJSON_String   (1 << 4)
#define cJSON_Array    (1 << 5)
#define cJSON_Object   (1 << 6)
#define cJSON_Raw      (1 << 7)

#define cJSON_IsFalse(x) ((x) && (x)->type == cJSON_False)
#define cJSON_IsTrue(x) ((x) && (x)->type == cJSON_True)
#define cJSON_IsBool(x) ((x) && ((x)->type == cJSON_True || (x)->type == cJSON_False))
#define cJSON_IsNull(x) ((x) && (x)->type == cJSON_NULL)
#define cJSON_IsNumber(x) ((x) && ((x)->type & cJSON_Number) != 0)
#define cJSON_IsString(x) ((x) && (x)->type == cJSON_String)
#define cJSON_IsArray(x) ((x) && (x)->type == cJSON_Array)
#define cJSON_IsObject(x) ((x) && (x)->type == cJSON_Object)

/* Public API */
cJSON *cJSON_Parse(const char *value);
char *cJSON_Print(const cJSON *item);
void cJSON_Delete(cJSON *item);
const char *cJSON_GetErrorPtr(void);

/* Object/Array helpers */
int cJSON_GetArraySize(const cJSON *array);
cJSON *cJSON_GetArrayItem(const cJSON *array, int index);
cJSON *cJSON_GetObjectItem(const cJSON *object, const char *string);
cJSON *cJSON_GetObjectItemCaseSensitive(const cJSON *object, const char *string);

#endif /* CJSON_H */

/*
 * cJSON.c - Minimal implementation of cJSON
 * Sufficient for engine-psx tools
 */

#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdio.h>
#include "cJSON.h"

static const char *ep; // error pointer

const char *cJSON_GetErrorPtr(void) {
    return ep;
}

static int skip(const char **c) {
    while (isspace((unsigned char)**c)) (*c)++;
    return **c != '\0';
}

static const char *parse_string(cJSON *item, const char *str) {
    const char *ptr = str + 1;
    char *ptr2;
    char *out;
    int len = 0;

    if (*str != '"') { ep = str; return NULL; }

    while (*ptr != '"' && *ptr) {
        if (*ptr++ == '\\') ptr++;
        len++;
    }

    out = (char*)malloc(len + 1);
    if (!out) return NULL;

    ptr = str + 1;
    ptr2 = out;
    while (*ptr != '"' && *ptr) {
        if (*ptr != '\\') *ptr2++ = *ptr++;
        else {
            ptr++;
            switch (*ptr++) {
                case 'b': *ptr2++ = '\b'; break;
                case 'f': *ptr2++ = '\f'; break;
                case 'n': *ptr2++ = '\n'; break;
                case 'r': *ptr2++ = '\r'; break;
                case 't': *ptr2++ = '\t'; break;
                default: *ptr2++ = *(ptr-1); break;
            }
        }
    }
    *ptr2 = '\0';

    if (*ptr == '"') ptr++;
    item->valuestring = out;
    item->type = cJSON_String;
    return ptr;
}

static const char *parse_number(cJSON *item, const char *num) {
    double n = 0;
    int sign = 1;

    if (*num == '-') sign = -1, num++;
    if (*num == '0') num++;
    if (*num >= '1' && *num <= '9') {
        do n = (n * 10.0) + (*num++ - '0'); while (*num >= '0' && *num <= '9');
    }
    if (*num == '.' && num[1] >= '0' && num[1] <= '9') {
        double frac = 0;
        int div = 1;
        num++;
        while (*num >= '0' && *num <= '9') {
            frac = (frac * 10.0) + (*num++ - '0');
            div *= 10;
        }
        n += frac / div;
    }
    if (*num == 'e' || *num == 'E') {
        int e = 0, esign = 1;
        num++;
        if (*num == '+') num++;
        else if (*num == '-') esign = -1, num++;
        while (*num >= '0' && *num <= '9') e = (e * 10) + (*num++ - '0');
        if (esign < 0) for (int i = 0; i < e; i++) n /= 10.0;
        else for (int i = 0; i < e; i++) n *= 10.0;
    }

    item->valuedouble = n * sign;
    item->valueint = (int)(n * sign);
    item->type = cJSON_Number;
    return num;
}

static const char *parse_value(cJSON *item, const char *value);

static const char *parse_array(cJSON *item, const char *value) {
    cJSON *child;
    if (*value != '[') { ep = value; return NULL; }

    item->type = cJSON_Array;
    value = skip(&value) + 1;

    if (*value == ']') return value + 1;

    item->child = child = (cJSON*)malloc(sizeof(cJSON));
    if (!item->child) return NULL;
    memset(item->child, 0, sizeof(cJSON));

    value = skip(&parse_value(child, skip(&value)));
    if (!value) return NULL;

    while (*value == ',') {
        cJSON *new_item = (cJSON*)malloc(sizeof(cJSON));
        if (!new_item) return NULL;
        memset(new_item, 0, sizeof(cJSON));
        child->next = new_item;
        new_item->prev = child;
        child = new_item;
        value = skip(&parse_value(child, skip(&value + 1)));
        if (!value) return NULL;
    }

    if (*value == ']') return value + 1;
    ep = value;
    return NULL;
}

static const char *parse_object(cJSON *item, const char *value) {
    cJSON *child;
    if (*value != '{') { ep = value; return NULL; }

    item->type = cJSON_Object;
    value = skip(&value) + 1;

    if (*value == '}') return value + 1;

    item->child = child = (cJSON*)malloc(sizeof(cJSON));
    if (!item->child) return NULL;
    memset(item->child, 0, sizeof(cJSON));

    const char *name = parse_string(child, skip(&value));
    if (!name) return NULL;
    child->string = child->valuestring;
    child->valuestring = NULL;

    value = skip(&name);
    if (*value != ':') { ep = value; return NULL; }
    value = skip(&parse_value(child, skip(&value + 1)));
    if (!value) return NULL;

    while (*value == ',') {
        cJSON *new_item = (cJSON*)malloc(sizeof(cJSON));
        if (!new_item) return NULL;
        memset(new_item, 0, sizeof(cJSON));
        child->next = new_item;
        new_item->prev = child;
        child = new_item;

        name = parse_string(child, skip(&value + 1));
        if (!name) return NULL;
        child->string = child->valuestring;
        child->valuestring = NULL;

        value = skip(&name);
        if (*value != ':') { ep = value; return NULL; }
        value = skip(&parse_value(child, skip(&value + 1)));
        if (!value) return NULL;
    }

    if (*value == '}') return value + 1;
    ep = value;
    return NULL;
}

static const char *parse_value(cJSON *item, const char *value) {
    if (!value) { ep = value; return NULL; }

    if (!strncmp(value, "null", 4)) { item->type = cJSON_NULL; return value + 4; }
    if (!strncmp(value, "false", 5)) { item->type = cJSON_False; return value + 5; }
    if (!strncmp(value, "true", 4)) { item->type = cJSON_True; return value + 4; }
    if (*value == '"') return parse_string(item, value);
    if (*value == '-' || (*value >= '0' && *value <= '9')) return parse_number(item, value);
    if (*value == '[') return parse_array(item, value);
    if (*value == '{') return parse_object(item, value);

    ep = value;
    return NULL;
}

cJSON *cJSON_Parse(const char *value) {
    cJSON *c = (cJSON*)malloc(sizeof(cJSON));
    if (!c) return NULL;
    memset(c, 0, sizeof(cJSON));

    ep = NULL;
    const char *end = parse_value(c, skip(&value));

    if (!end || *skip(&end)) {
        cJSON_Delete(c);
        return NULL;
    }
    return c;
}

void cJSON_Delete(cJSON *c) {
    cJSON *next;
    while (c) {
        next = c->next;
        if (c->child) cJSON_Delete(c->child);
        if (c->valuestring) free(c->valuestring);
        if (c->string) free(c->string);
        free(c);
        c = next;
    }
}

int cJSON_GetArraySize(const cJSON *array) {
    int size = 0;
    cJSON *c = array ? array->child : NULL;
    while (c) { size++; c = c->next; }
    return size;
}

cJSON *cJSON_GetArrayItem(const cJSON *array, int item) {
    cJSON *c = array ? array->child : NULL;
    while (c && item > 0) { item--; c = c->next; }
    return c;
}

cJSON *cJSON_GetObjectItem(const cJSON *object, const char *string) {
    cJSON *c = object ? object->child : NULL;
    while (c && strcmp(c->string, string)) c = c->next;
    return c;
}

cJSON *cJSON_GetObjectItemCaseSensitive(const cJSON *object, const char *string) {
    return cJSON_GetObjectItem(object, string);
}

char *cJSON_Print(const cJSON *item) {
    // Minimal implementation - not used by tools
    return NULL;
}

/*
 * toml.h - Minimal TOML parser interface
 * For full version, see: https://github.com/cktan/tomlc99
 */

#ifndef TOML_H
#define TOML_H

#include <stdio.h>
