/*
 * cJSON.c - Minimal implementation of cJSON
 * Sufficient for engine-psx tools
 */

#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdio.h>
#include <stdbool.h>
#include "cJSON.h"

static const char *ep; // error pointer

const char *cJSON_GetErrorPtr(void) {
    return ep;
}

static const char* skip_ws(const char *c) {
    while (isspace((unsigned char)*c)) c++;
    return c;
}

static const char *parse_string(cJSON *item, const char *str) {
    const char *ptr = str + 1;
    char *ptr2;
    char *out;
    int len = 0;

    if (*str != '"') { ep = str; return NULL; }

    while (*ptr != '"' && *ptr) {
        if (*ptr++ == '\\') ptr++;
        len++;
    }

    out = (char*)malloc(len + 1);
    if (!out) return NULL;

    ptr = str + 1;
    ptr2 = out;
    while (*ptr != '"' && *ptr) {
        if (*ptr != '\\') *ptr2++ = *ptr++;
        else {
            ptr++;
            switch (*ptr++) {
                case 'b': *ptr2++ = '\b'; break;
                case 'f': *ptr2++ = '\f'; break;
                case 'n': *ptr2++ = '\n'; break;
                case 'r': *ptr2++ = '\r'; break;
                case 't': *ptr2++ = '\t'; break;
                default: *ptr2++ = *(ptr-1); break;
            }
        }
    }
    *ptr2 = '\0';

    if (*ptr == '"') ptr++;
    item->valuestring = out;
    item->type = cJSON_String;
    return ptr;
}

static const char *parse_number(cJSON *item, const char *num) {
    double n = 0;
    int sign = 1;

    if (*num == '-') sign = -1, num++;
    if (*num == '0') num++;
    if (*num >= '1' && *num <= '9') {
        do n = (n * 10.0) + (*num++ - '0'); while (*num >= '0' && *num <= '9');
    }
    if (*num == '.' && num[1] >= '0' && num[1] <= '9') {
        double frac = 0;
        int div = 1;
        num++;
        while (*num >= '0' && *num <= '9') {
            frac = (frac * 10.0) + (*num++ - '0');
            div *= 10;
        }
        n += frac / div;
    }
    if (*num == 'e' || *num == 'E') {
        int e = 0, esign = 1;
        num++;
        if (*num == '+') num++;
        else if (*num == '-') esign = -1, num++;
        while (*num >= '0' && *num <= '9') e = (e * 10) + (*num++ - '0');
        if (esign < 0) for (int i = 0; i < e; i++) n /= 10.0;
        else for (int i = 0; i < e; i++) n *= 10.0;
    }

    item->valuedouble = n * sign;
    item->valueint = (int)(n * sign);
    item->type = cJSON_Number;
    return num;
}

static const char *parse_value(cJSON *item, const char *value);

static const char *parse_array(cJSON *item, const char *value) {
    cJSON *child;
    if (*value != '[') { ep = value; return NULL; }

    item->type = cJSON_Array;
    value = skip_ws(value + 1);

    if (*value == ']') return value + 1;

    item->child = child = (cJSON*)malloc(sizeof(cJSON));
    if (!item->child) return NULL;
    memset(item->child, 0, sizeof(cJSON));

    value = parse_value(child, skip_ws(value));
    if (!value) return NULL;

    while (*value == ',') {
        cJSON *new_item = (cJSON*)malloc(sizeof(cJSON));
        if (!new_item) return NULL;
        memset(new_item, 0, sizeof(cJSON));
        child->next = new_item;
        new_item->prev = child;
        child = new_item;
        value = skip_ws(value + 1);
        value = parse_value(child, value);
        if (!value) return NULL;
    }

    if (*value == ']') return value + 1;
    ep = value;
    return NULL;
}

static const char *parse_object(cJSON *item, const char *value) {
    cJSON *child;
    if (*value != '{') { ep = value; return NULL; }

    item->type = cJSON_Object;
    value = skip_ws(value + 1);

    if (*value == '}') return value + 1;

    item->child = child = (cJSON*)malloc(sizeof(cJSON));
    if (!item->child) return NULL;
    memset(item->child, 0, sizeof(cJSON));

    const char *name = parse_string(child, skip_ws(value));
    if (!name) return NULL;
    child->string = child->valuestring;
    child->valuestring = NULL;

    value = skip_ws(name);
    if (*value != ':') { ep = value; return NULL; }
    value = skip_ws(value + 1);
    value = parse_value(child, value);
    if (!value) return NULL;

    while (*value == ',') {
        cJSON *new_item = (cJSON*)malloc(sizeof(cJSON));
        if (!new_item) return NULL;
        memset(new_item, 0, sizeof(cJSON));
        child->next = new_item;
        new_item->prev = child;
        child = new_item;

        value = skip_ws(value + 1);
        name = parse_string(child, value);
        if (!name) return NULL;
        child->string = child->valuestring;
        child->valuestring = NULL;

        value = skip_ws(name);
        if (*value != ':') { ep = value; return NULL; }
        value = skip_ws(value + 1);
        value = parse_value(child, value);
        if (!value) return NULL;
    }

    if (*value == '}') return value + 1;
    ep = value;
    return NULL;
}

static const char *parse_value(cJSON *item, const char *value) {
    if (!value) { ep = value; return NULL; }

    if (!strncmp(value, "null", 4)) { item->type = cJSON_NULL; return value + 4; }
    if (!strncmp(value, "false", 5)) { item->type = cJSON_False; return value + 5; }
    if (!strncmp(value, "true", 4)) { item->type = cJSON_True; return value + 4; }
    if (*value == '"') return parse_string(item, value);
    if (*value == '-' || (*value >= '0' && *value <= '9')) return parse_number(item, value);
    if (*value == '[') return parse_array(item, value);
    if (*value == '{') return parse_object(item, value);

    ep = value;
    return NULL;
}

cJSON *cJSON_Parse(const char *value) {
    cJSON *c = (cJSON*)malloc(sizeof(cJSON));
    if (!c) return NULL;
    memset(c, 0, sizeof(cJSON));

    ep = NULL;
    const char *end = parse_value(c, skip_ws(value));

    if (!end || *skip_ws(end)) {
        cJSON_Delete(c);
        return NULL;
    }
    return c;
}

void cJSON_Delete(cJSON *c) {
    cJSON *next;
    while (c) {
        next = c->next;
        if (c->child) cJSON_Delete(c->child);
        if (c->valuestring) free(c->valuestring);
        if (c->string) free(c->string);
        free(c);
        c = next;
    }
}

int cJSON_GetArraySize(const cJSON *array) {
    int size = 0;
    cJSON *c = array ? array->child : NULL;
    while (c) { size++; c = c->next; }
    return size;
}

cJSON *cJSON_GetArrayItem(const cJSON *array, int item) {
    cJSON *c = array ? array->child : NULL;
    while (c && item > 0) { item--; c = c->next; }
    return c;
}

cJSON *cJSON_GetObjectItem(const cJSON *object, const char *string) {
    cJSON *c = object ? object->child : NULL;
    while (c && strcmp(c->string, string)) c = c->next;
    return c;
}

cJSON *cJSON_GetObjectItemCaseSensitive(const cJSON *object, const char *string) {
    return cJSON_GetObjectItem(object, string);
}

char *cJSON_Print(const cJSON *item) {
    (void)item;
    return NULL;
}

/*
 * tomlc99.c - Minimal TOML implementation for buildprl
 * Supports: tables, key=value (int, float, bool), basic strings
 */

#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <errno.h>
#include <stdio.h>
#include "toml.h"

#define ERROR(f, ...) do { snprintf(errbuf, errbufsz, f, ##__VA_ARGS__); return NULL; } while(0)

static char *errbuf;
static int errbufsz;

/* Context for parsing */
typedef struct {
    char *src;
    char *p;
    int len;
    toml_table_t *root;
} parse_ctx;

/* Table entry types */
typedef enum entry_type {
    ENTRY_TABLE,
    ENTRY_ARRAY,
    ENTRY_STRING,
    ENTRY_INT,
    ENTRY_DOUBLE,
    ENTRY_BOOL
} entry_type;

/* Table entry */
typedef struct entry {
    struct entry *next;
    char *key;
    entry_type type;
    union {
        toml_table_t *tab;
        toml_array_t *arr;
        char *s;
        int64_t i;
        double d;
        int b;
    } u;
} entry;

/* Table struct */
struct toml_table {
    char *name;
    entry *first;
    entry *last;
};

/* Array struct */
struct toml_array {
    int nelem;
    entry *first;
    entry *last;
};

/* Skip whitespace incl newlines */
static void skip_ws(parse_ctx *ctx) {
    while (*ctx->p) {
        if (*ctx->p == '#') {
            while (*ctx->p && *ctx->p != '\n') ctx->p++;
        }
        if (!isspace((unsigned char)*ctx->p)) break;
        ctx->p++;
    }
}

/* Parse a basic string (unquoted, no spaces) */
static char *parse_bare_key(parse_ctx *ctx) {
    char *start = ctx->p;
    while (*ctx->p && (isalnum((unsigned char)*ctx->p) || *ctx->p == '_' || *ctx->p == '-'))
        ctx->p++;

    int len = ctx->p - start;
    if (len == 0) return NULL;

    char *s = malloc(len + 1);
    memcpy(s, start, len);
    s[len] = '\0';
    return s;
}

/* Parse quoted string */
static char *parse_quoted_string(parse_ctx *ctx) {
    char quote = *ctx->p;
    if (quote != '"' && quote != '\'') return NULL;
    ctx->p++;

    char *start = ctx->p;
    int len = 0;

    while (*ctx->p && *ctx->p != quote) {
        if (*ctx->p == '\\') {
            ctx->p++; // Skip escape char
            if (*ctx->p) ctx->p++;
        } else {
            ctx->p++;
        }
        len++;
    }

    if (*ctx->p != quote) return NULL;
    ctx->p++;

    char *s = malloc(len + 1);
    memcpy(s, start, len);  // Simplified: no escape processing
    s[len] = '\0';
    return s;
}

/* Parse value into entry */
static entry* parse_value(parse_ctx *ctx) {
    skip_ws(ctx);
    entry *e = calloc(1, sizeof(entry));

    if (*ctx->p == '{') {
        // Inline table - treat as string placeholder
        e->type = ENTRY_STRING;
        e->u.s = strdup("{}");
        ctx->p++;
        while (*ctx->p && *ctx->p != '}') ctx->p++;
        if (*ctx->p == '}') ctx->p++;
        return e;
    }

    if (*ctx->p == '[') {
        // Array
        ctx->p++;
        e->type = ENTRY_ARRAY;
        e->u.arr = calloc(1, sizeof(toml_array_t));

        while (1) {
            skip_ws(ctx);
            if (*ctx->p == ']') { ctx->p++; break; }

            entry *elem = parse_value(ctx);
            if (!elem) return NULL;

            if (!e->u.arr->first) e->u.arr->first = elem;
            else e->u.arr->last->next = elem;
            e->u.arr->last = elem;
            e->u.arr->nelem++;

            skip_ws(ctx);
            if (*ctx->p == ',') { ctx->p++; continue; }
            if (*ctx->p == ']') { ctx->p++; break; }
        }
        return e;
    }

    if (*ctx->p == '"' || *ctx->p == '\'') {
        e->type = ENTRY_STRING;
        e->u.s = parse_quoted_string(ctx);
        return e;
    }

    // Try bool
    if (!strncmp(ctx->p, "true", 4)) {
        e->type = ENTRY_BOOL;
        e->u.b = 1;
        ctx->p += 4;
        return e;
    }
    if (!strncmp(ctx->p, "false", 5)) {
        e->type = ENTRY_BOOL;
        e->u.b = 0;
        ctx->p += 5;
        return e;
    }

    // Try number
    char *end;
    errno = 0;

    // Check for float first
    double dval = strtod(ctx->p, &end);
    if (end != ctx->p) {
        // Check if it's actually an int
        if (strchr(ctx->p, '.') == NULL && strchr(ctx->p, 'e') == NULL && strchr(ctx->p, 'E') == NULL) {
            e->type = ENTRY_INT;
            e->u.i = strtoll(ctx->p, &end, 10);
        } else {
            e->type = ENTRY_DOUBLE;
            e->u.d = dval;
        }
        ctx->p = end;
        return e;
    }

    // Bare string fallback
    e->type = ENTRY_STRING;
    e->u.s = parse_bare_key(ctx);
    return e ? e : NULL;
}

/* Find or create table entry */
static entry* find_entry(toml_table_t *tab, const char *key) {
    for (entry *e = tab->first; e; e = e->next) {
        if (e->key && !strcmp(e->key, key)) return e;
    }
    return NULL;
}

/* Add entry to table */
static void add_entry(toml_table_t *tab, entry *e) {
    if (!tab->first) tab->first = e;
    else tab->last->next = e;
    tab->last = e;
}

/* Parse table body */
static int parse_table_body(parse_ctx *ctx, toml_table_t *tab) {
    while (1) {
        skip_ws(ctx);
        if (*ctx->p == '\0' || *ctx->p == '[') break;

        // Parse key
        char *key = parse_bare_key(ctx);
        if (!key) break;

        skip_ws(ctx);
        if (*ctx->p != '=') {
            free(key);
            break;
        }
        ctx->p++;

        // Parse value
        entry *e = parse_value(ctx);
        if (!e) {
            free(key);
            return -1;
        }
        e->key = key;
        add_entry(tab, e);
    }
    return 0;
}

toml_table_t *toml_parse(char *toml, char *errbuf_in, int errbufsz_in) {
    errbuf = errbuf_in;
    errbufsz = errbufsz_in;

    parse_ctx ctx = {
        .src = toml,
        .p = toml,
        .len = (int)strlen(toml),
        .root = calloc(1, sizeof(toml_table_t))
    };

    if (!parse_table_body(&ctx, ctx.root)) {
        // Try parsing as table sections
        while (*ctx.p) {
            skip_ws(&ctx);
            if (*ctx.p != '[') break;
            ctx.p++; // skip [

            char *sec = parse_bare_key(&ctx);
            if (!sec) break;

            if (*ctx.p == ']') ctx.p++;

            // Create subtable
            entry *e = calloc(1, sizeof(entry));
            e->key = sec;
            e->type = ENTRY_TABLE;
            e->u.tab = calloc(1, sizeof(toml_table_t));
            e->u.tab->name = strdup(sec);
            add_entry(ctx.root, e);

            skip_ws(&ctx);
            parse_table_body(&ctx, e->u.tab);
        }
    }

    return ctx.root;
}

toml_table_t *toml_parse_file(FILE *fp, char *errbuf_in, int errbufsz_in) {
    fseek(fp, 0, SEEK_END);
    long len = ftell(fp);
    fseek(fp, 0, SEEK_SET);

    char *buf = malloc(len + 1);
    if (!buf) return NULL;
    fread(buf, 1, len, fp);
    buf[len] = '\0';

    toml_table_t *t = toml_parse(buf, errbuf_in, errbufsz_in);
    free(buf);
    return t;
}

void toml_free(toml_table_t *tab) {
    if (!tab) return;
    entry *e = tab->first;
    while (e) {
        entry *next = e->next;
        free(e->key);
        if (e->type == ENTRY_STRING) free(e->u.s);
        else if (e->type == ENTRY_TABLE) toml_free(e->u.tab);
        else if (e->type == ENTRY_ARRAY) {
            entry *ae = e->u.arr->first;
            while (ae) { entry *an = ae->next; free(ae); ae = an; }
            free(e->u.arr);
        }
        free(e);
        e = next;
    }
    free(tab->name);
    free(tab);
}

int toml_key_exists(toml_table_t *tab, const char *key) {
    return find_entry(tab, key) != NULL;
}

const char *toml_key_in(toml_table_t *tab, int keyidx) {
    entry *e = tab->first;
    while (keyidx-- > 0 && e) e = e->next;
    return e ? e->key : NULL;
}

toml_table_t *toml_table_in(toml_table_t *tab, const char *key) {
    entry *e = find_entry(tab, key);
    return (e && e->type == ENTRY_TABLE) ? e->u.tab : NULL;
}

toml_array_t *toml_array_in(toml_table_t *tab, const char *key) {
    entry *e = find_entry(tab, key);
    return (e && e->type == ENTRY_ARRAY) ? e->u.arr : NULL;
}

toml_datum_t toml_string_in(toml_table_t *tab, const char *key) {
    toml_datum_t d = {.ok = 0};
    entry *e = find_entry(tab, key);
    if (e && e->type == ENTRY_STRING) {
        d.ok = 1;
        d.u.s = e->u.s;
    }
    return d;
}

toml_datum_t toml_int_in(toml_table_t *tab, const char *key) {
    toml_datum_t d = {.ok = 0};
    entry *e = find_entry(tab, key);
    if (e && e->type == ENTRY_INT) {
        d.ok = 1;
        d.u.i = e->u.i;
    }
    return d;
}

toml_datum_t toml_double_in(toml_table_t *tab, const char *key) {
    toml_datum_t d = {.ok = 0};
    entry *e = find_entry(tab, key);
    if (e && e->type == ENTRY_DOUBLE) {
        d.ok = 1;
        d.u.d = e->u.d;
    }
    return d;
}

toml_datum_t toml_bool_in(toml_table_t *tab, const char *key) {
    toml_datum_t d = {.ok = 0};
    entry *e = find_entry(tab, key);
    if (e && e->type == ENTRY_BOOL) {
        d.ok = 1;
        d.u.b = e->u.b;
    }
    return d;
}

toml_datum_t toml_int_at(toml_array_t *arr, int idx) {
    toml_datum_t d = {.ok = 0};
    entry *e = arr->first;
    while (idx-- > 0 && e) e = e->next;
    if (e && e->type == ENTRY_INT) {
        d.ok = 1;
        d.u.i = e->u.i;
    }
    return d;
}

toml_datum_t toml_double_at(toml_array_t *arr, int idx) {
    toml_datum_t d = {.ok = 0};
    entry *e = arr->first;
    while (idx-- > 0 && e) e = e->next;
    if (e && e->type == ENTRY_DOUBLE) {
        d.ok = 1;
        d.u.d = e->u.d;
    }
    return d;
}

