/*
 * buildprl.c - Convert parallax TOML to binary PRL format
 * Replaces buildprl.py
 * 
 * Output: PRL.PRL in same directory as input TOML
 * 
 * Binary layout:
 * - num_strips (u8)
 * For each strip:
 *   - u0 (u8), v0 (u8)
 *   - width (u16 BE), height (u16 BE)
 *   - bg_index (u8)
 *   - single (u8)
 *   - scrollx (s32 BE - 20.12 fixed)
 *   - speedx (s32 BE - 20.12 fixed)
 *   - y0 (s16 BE)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <libgen.h>
#include "toml.h"
#include "psxtypes.h"

#define MAX_STRIPS 256

typedef struct {
    u8 u0;
    u8 v0;
    u16 width;
    u16 height;
    u8 bg_index;
    u8 single;
    s32 scrollx;  // 20.12 fixed point
    s32 speedx;   // 20.12 fixed point
    s16 y0;
} ParallaxStrip;

typedef struct {
    int num_strips;
    ParallaxStrip strips[MAX_STRIPS];
} ParallaxData;

static inline s32 float_to_fixed12(float f) {
    return (s32)(f * 4096.0f);
}

void print_usage(const char *prog) {
    fprintf(stderr, "Usage: %s <parallax.toml>\n", prog);
    fprintf(stderr, "Output: PRL.PRL in same directory as input\n");
}

const char* get_output_path(const char *input_path) {
    static char output_path[1024];
    char *copy = strdup(input_path);
    char *dir = dirname(copy);

    if (strlen(dir) > 0) {
        snprintf(output_path, sizeof(output_path), "%s/PRL.PRL", dir);
    } else {
        snprintf(output_path, sizeof(output_path), "PRL.PRL");
    }

    free(copy);
    return output_path;
}

int parse_parallax(const char *filename, ParallaxData *prl) {
    FILE *f = fopen(filename, "r");
    if (!f) {
        fprintf(stderr, "Error: cannot open %s\n", filename);
        return -1;
    }

    // Read entire file
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = malloc(size + 1);
    fread(buf, 1, size, f);
    buf[size] = '\0';
    fclose(f);

    char errbuf[256];
    toml_table_t *root = toml_parse(buf, errbuf, sizeof(errbuf));
    free(buf);

    if (!root) {
        fprintf(stderr, "Error: TOML parse failed: %s\n", errbuf);
        return -1;
    }

    // Iterate through all keys in root table (each is a strip)
    int num_strips = 0;
    for (int i = 0; ; i++) {
        const char *key = toml_key_in(root, i);
        if (!key) break;

        toml_table_t *strip = toml_table_in(root, key);
        if (!strip) continue;

        if (num_strips >= MAX_STRIPS) {
            fprintf(stderr, "Warning: max strips (%d) reached, ignoring rest\n", MAX_STRIPS);
            break;
        }

        ParallaxStrip *s = &prl->strips[num_strips];
        memset(s, 0, sizeof(ParallaxStrip));

        // Read values with defaults
        toml_datum_t u0 = toml_int_in(strip, "u0");
        toml_datum_t v0 = toml_int_in(strip, "v0");
        toml_datum_t width = toml_int_in(strip, "width");
        toml_datum_t height = toml_int_in(strip, "height");
        toml_datum_t y0 = toml_int_in(strip, "y0");

        // Optional floats
        toml_datum_t scrollx = toml_double_in(strip, "scrollx");
        toml_datum_t speedx = toml_double_in(strip, "speedx");

        // Optional bool
        toml_datum_t single = toml_bool_in(strip, "single");

        s->u0 = u0.ok ? (u8)u0.u.i : 0;
        s->v0 = v0.ok ? (u8)v0.u.i : 0;
        s->width = width.ok ? (u16)width.u.i : 0;
        s->height = height.ok ? (u16)height.u.i : 0;
        s->y0 = y0.ok ? (s16)y0.u.i : 0;

        // Calculate bg_index and actual v0
        s->bg_index = (s->v0 >= 256) ? (s->v0 / 256) : 0;
        s->v0 = s->v0 % 256;

        s->scrollx = scrollx.ok ? float_to_fixed12((float)scrollx.u.d) : 0;
        s->speedx = speedx.ok ? float_to_fixed12((float)speedx.u.d) : 0;
        s->single = single.ok ? (single.u.b ? 1 : 0) : 0;

        printf("Strip %s: u0=%d v0=%d (%d:%d) %dx%d y0=%d\n", 
               key, s->u0, s->v0, s->bg_index, s->v0, 
               s->width, s->height, s->y0);

        num_strips++;
    }

    prl->num_strips = num_strips;
    toml_free(root);

    printf("Total strips: %d\n", num_strips);
    return 0;
}

int write_parallax(const char *filename, const ParallaxData *prl) {
    FILE *f = fopen(filename, "wb");
    if (!f) {
        fprintf(stderr, "Error: cannot create %s\n", filename);
        return -1;
    }

    // Write number of strips
    write_u8(f, (u8)prl->num_strips);

    // Write each strip
    for (int i = 0; i < prl->num_strips; i++) {
        const ParallaxStrip *s = &prl->strips[i];
        write_u8(f, s->u0);
        write_u8(f, s->v0);
        write_u16_be(f, s->width);
        write_u16_be(f, s->height);
        write_u8(f, s->bg_index);
        write_u8(f, s->single);
        write_s32_be(f, s->scrollx);
        write_s32_be(f, s->speedx);
        write_s16_be(f, s->y0);
    }

    fclose(f);
    printf("Created %s\n", filename);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        print_usage(argv[0]);
        return 1;
    }

    const char *input = argv[1];
    const char *output = get_output_path(input);

    ParallaxData prl = {0};

    if (parse_parallax(input, &prl) != 0) {
        return 1;
    }

    if (write_parallax(output, &prl) != 0) {
        return 1;
    }

    return 0;
}

/*
 * chunkgen.c - Convert 128x128 chunks from CSV to MAP binary format
 * Replaces chunkgen.py
 * 
 * Binary layout:
 * - tile_width (u16 BE) - always 128
 * - num_tiles (u16 BE) - grid_width * grid_height
 * - frame_dim (u16 BE) - always 8
 * - For each chunk:
 *   - For each of 8x8 tiles:
 *     - tile_index (u16 BE)
 *     - props (u8) - 0=solid, 1=oneway, 2=nocol, 4=front
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <cctype>
#include <math.h>
#include "psxtypes.h"

#define CHUNK_SIZE 8
#define TILE_WIDTH 128

// Layer type enum
enum LayerType {
    LAYER_SOLID = 0,
    LAYER_ONEWAY = 1,
    LAYER_NOCOL = 2,
    LAYER_FRONT = 3,
    MAX_LAYERS = 4
};

// Simple CSV matrix
typedef struct {
    int *data;
    int rows;
    int cols;
} Matrix;

void matrix_free(Matrix *m) {
    if (m) {
        free(m->data);
        m->data = NULL;
        m->rows = m->cols = 0;
    }
}

// Round up dimension to multiple of 8
int round_up_8(int d) {
    if (d % 8 > 0) {
        return d + (8 - (d % 8));
    }
    return d;
}

// Get chunk at position
void get_chunk(const Matrix *m, int cx, int cy, int *out) {
    int startx = cx * CHUNK_SIZE;
    int starty = cy * CHUNK_SIZE;

    for (int y = 0; y < CHUNK_SIZE; y++) {
        for (int x = 0; x < CHUNK_SIZE; x++) {
            int row = starty + y;
            int col = startx + x;
            int idx = y * CHUNK_SIZE + x;

            if (row < m->rows && col < m->cols) {
                out[idx] = m->data[row * m->cols + col];
            } else {
                out[idx] = -1;  // Empty
            }
        }
    }
}

// Parse CSV file
Matrix* csv_load(const char *filename) {
    FILE *f = fopen(filename, "r");
    if (!f) return NULL;

    Matrix *m = (Matrix*)calloc(1, sizeof(Matrix));

    // First pass: count rows and max columns
    char line[16384];
    int cols = 0, max_cols = 0;
    int rows = 0;

    while (fgets(line, sizeof(line), f)) {
        cols = 0;
        char *p = line;
        while (*p) {
            // Skip whitespace
            while (*p == ' ' || *p == '\t' || *p == '\r') p++;
            if (*p == '\n' || *p == '\0') break;

            // Parse number
            if (*p == '-') {
                p++; // Skip minus
                while (isdigit((unsigned char)*p)) p++;
                cols++;
            } else if (isdigit((unsigned char)*p)) {
                while (isdigit((unsigned char)*p)) p++;
                cols++;
            } else if (*p == ',') {
                p++;
            } else {
                p++;
            }
        }
        if (cols > 0) {
            rows++;
            if (cols > max_cols) max_cols = cols;
        }
    }

    // Round up dimensions
    int final_cols = round_up_8(max_cols);
    int final_rows = round_up_8(rows);

    // Allocate and init with -1
    m->data = (int*)malloc(final_rows * final_cols * sizeof(int));
    for (int i = 0; i < final_rows * final_cols; i++) {
        m->data[i] = -1;
    }
    m->rows = final_rows;
    m->cols = final_cols;

    // Second pass: fill data
    rewind(f);
    int row = 0;

    while (fgets(line, sizeof(line), f) && row < final_rows) {
        int col = 0;
        char *p = line;

        while (*p && col < final_cols) {
            // Skip whitespace
            while (*p == ' ' || *p == '\t' || *p == '\r') p++;
            if (*p == '\n' || *p == '\0') break;
            if (*p == ',') {
                p++;
                continue;
            }

            // Parse number
            char *end;
            long val = strtol(p, &end, 10);
            if (end != p) {
                m->data[row * final_cols + col] = (int)val;
                col++;
                p = end;
            } else {
                p++;
            }
        }
        row++;
    }

    fclose(f);
    return m;
}

// Get grid dimensions
void get_grid_size(const Matrix *m, int *grid_w, int *grid_h) {
    *grid_w = m->cols / CHUNK_SIZE;
    *grid_h = m->rows / CHUNK_SIZE;
}

// Export binary
void export_binary(FILE *f, Matrix *layers[MAX_LAYERS]) {
    Matrix *solid = layers[LAYER_SOLID];
    int grid_w, grid_h;
    get_grid_size(solid, &grid_w, &grid_h);
    int num_chunks = grid_w * grid_h;

    // Header
    write_u16_be(f, TILE_WIDTH);
    write_u16_be(f, (u16)num_chunks);
    write_u16_be(f, CHUNK_SIZE);

    printf("Grid: %dx%d = %d chunks\n", grid_w, grid_h, num_chunks);

    // For each chunk
    for (int cy = 0; cy < grid_h; cy++) {
        for (int cx = 0; cx < grid_w; cx++) {
            int solid_chunk[CHUNK_SIZE * CHUNK_SIZE];
            int oneway_chunk[CHUNK_SIZE * CHUNK_SIZE] = {0};
            int nocol_chunk[CHUNK_SIZE * CHUNK_SIZE] = {0};
            int front_chunk[CHUNK_SIZE * CHUNK_SIZE] = {0};

            get_chunk(solid, cx, cy, solid_chunk);

            if (layers[LAYER_ONEWAY]) {
                get_chunk(layers[LAYER_ONEWAY], cx, cy, oneway_chunk);
            }
            if (layers[LAYER_NOCOL]) {
                get_chunk(layers[LAYER_NOCOL], cx, cy, nocol_chunk);
            }
            if (layers[LAYER_FRONT]) {
                get_chunk(layers[LAYER_FRONT], cx, cy, front_chunk);
            }

            // For each tile in chunk (row-major)
            for (int py = 0; py < CHUNK_SIZE; py++) {
                for (int px = 0; px < CHUNK_SIZE; px++) {
                    int idx = py * CHUNK_SIZE + px;
                    int tile_index = solid_chunk[idx];
                    u8 props = 0;

                    // Check alternative layers if solid is empty
                    if (tile_index <= 0 && layers[LAYER_ONEWAY] && oneway_chunk[idx] > 0) {
                        tile_index = oneway_chunk[idx];
                        props = 1;
                    }
                    if (tile_index <= 0 && layers[LAYER_NOCOL] && nocol_chunk[idx] > 0) {
                        tile_index = nocol_chunk[idx];
                        props = 2;
                    }
                    if (tile_index <= 0 && layers[LAYER_FRONT] && front_chunk[idx] > 0) {
                        tile_index = front_chunk[idx];
                        props = 4;
                    }

                    write_u16_be(f, (u16)(tile_index > 0 ? tile_index : 0));
                    write_u8(f, props);
                }
            }
        }
    }
}

void print_usage(const char *prog) {
    fprintf(stderr, "Usage: %s <input> <output.MAP>\n", prog);
    fprintf(stderr, "  input: either a single .cnk file or base path\n");
    fprintf(stderr, "         (will look for _solid.cnk, _oneway.cnk, etc.)\n");
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        print_usage(argv[0]);
        return 1;
    }

    const char *input = argv[1];
    const char *output = argv[2];

    Matrix *layers[MAX_LAYERS] = {0};

    // Check if single file or base path
    if (strstr(input, ".cnk")) {
        // Single mode
        layers[LAYER_SOLID] = csv_load(input);
        if (!layers[LAYER_SOLID]) {
            fprintf(stderr, "Error: cannot load %s\n", input);
            return 1;
        }
        printf("Loaded %s: %dx%d\n", input, layers[LAYER_SOLID]->cols, layers[LAYER_SOLID]->rows);
    } else {
        // Multi-layer mode
        char path[1024];

        // Solid (required)
        snprintf(path, sizeof(path), "%s_solid.cnk", input);
        layers[LAYER_SOLID] = csv_load(path);
        if (!layers[LAYER_SOLID]) {
            fprintf(stderr, "Error: cannot load %s\n", path);
            return 1;
        }
        printf("Loaded %s: %dx%d\n", path, layers[LAYER_SOLID]->cols, layers[LAYER_SOLID]->rows);

        // Optional layers
        snprintf(path, sizeof(path), "%s_oneway.cnk", input);
        FILE *test = fopen(path, "r");
        if (test) {
            fclose(test);
            layers[LAYER_ONEWAY] = csv_load(path);
            if (layers[LAYER_ONEWAY]) {
                printf("Loaded %s: %dx%d\n", path, layers[LAYER_ONEWAY]->cols, layers[LAYER_ONEWAY]->rows);
            }
        }

        snprintf(path, sizeof(path), "%s_none.cnk", input);
        test = fopen(path, "r");
        if (test) {
            fclose(test);
            layers[LAYER_NOCOL] = csv_load(path);
            if (layers[LAYER_NOCOL]) {
                printf("Loaded %s: %dx%d\n", path, layers[LAYER_NOCOL]->cols, layers[LAYER_NOCOL]->rows);
            }
        }

        snprintf(path, sizeof(path), "%s_front.cnk", input);
        test = fopen(path, "r");
        if (test) {
            fclose(test);
            layers[LAYER_FRONT] = csv_load(path);
            if (layers[LAYER_FRONT]) {
                printf("Loaded %s: %dx%d\n", path, layers[LAYER_FRONT]->cols, layers[LAYER_FRONT]->rows);
            }
        }
    }

    FILE *f = fopen(output, "wb");
    if (!f) {
        fprintf(stderr, "Error: cannot create %s\n", output);
        goto cleanup;
    }

    export_binary(f, layers);
    fclose(f);

    printf("Successfully wrote %s\n", output);

cleanup:
    for (int i = 0; i < MAX_LAYERS; i++) {
        matrix_free(layers[i]);
    }

    return 0;
}

