/*
 * tomlc99.c - Minimal TOML implementation for buildprl
 * Supports: tables, key=value (int, float, bool), comments
 */

#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <errno.h>
#include <stdio.h>
#include "toml.h"

typedef struct {
    char *data;
    char *p;
} toml_parser;

static void skip_whitespace_and_comments(toml_parser *p) {
    while (1) {
        // Skip whitespace
        while (*p->p && isspace((unsigned char)*p->p)) p->p++;

        // Skip comments
        if (*p->p == '#') {
            while (*p->p && *p->p != '\n') p->p++;
            continue;
        }
        break;
    }
}

static char *parse_key(toml_parser *p) {
    skip_whitespace_and_comments(p);

    char *start = p->p;
    while (*p->p && (isalnum((unsigned char)*p->p) || *p->p == '_' || *p->p == '-')) {
        p->p++;
    }

    int len = p->p - start;
    if (len == 0) return NULL;

    char *key = malloc(len + 1);
    memcpy(key, start, len);
    key[len] = '\0';
    return key;
}

static int parse_value(toml_parser *p, toml_datum_t *out) {
    skip_whitespace_and_comments(p);

    if (!*p->p) return -1;

    // Try bool
    if (strncmp(p->p, "true", 4) == 0 && !isalnum((unsigned char)p->p[4])) {
        out->ok = 1;
        out->u.b = 1;
        p->p += 4;
        return 0;
    }
    if (strncmp(p->p, "false", 5) == 0 && !isalnum((unsigned char)p->p[5])) {
        out->ok = 1;
        out->u.b = 0;
        p->p += 5;
        return 0;
    }

    // Try number
    char *end;

    // Check if starts with digit or minus
    if (isdigit((unsigned char)*p->p) || *p->p == '-') {
        // Try integer first
        long long ival = strtoll(p->p, &end, 10);
        if (end != p->p) {
            // Check if followed by . or e (then it's a float)
            if (*end == '.' || *end == 'e' || *end == 'E') {
                double dval = strtod(p->p, &end);
                if (end != p->p) {
                    out->ok = 1;
                    out->u.d = dval;
                    p->p = end;
                    return 0;
                }
            } else {
                out->ok = 1;
                out->u.i = ival;
                p->p = end;
                return 0;
            }
        }
    }

    // Try float starting with .
    if (*p->p == '.') {
        double dval = strtod(p->p, &end);
        if (end != p->p) {
            out->ok = 1;
            out->u.d = dval;
            p->p = end;
            return 0;
        }
    }

    return -1;
}

static toml_table_t *new_table(void) {
    return calloc(1, sizeof(toml_table_t));
}

toml_table_t *toml_parse(char *toml, char *errbuf, int errbufsz) {
    (void)errbuf;
    (void)errbufsz;

    toml_parser p = { .data = toml, .p = toml };
    toml_table_t *root = new_table();
    toml_table_t *current = root;

    while (1) {
        skip_whitespace_and_comments(&p);
        if (!*p.p) break;

        // Check for table header [section]
        if (*p.p == '[') {
            p.p++; // skip [
            char *section = parse_key(&p);
            if (!section) break;

            // Skip to ]
            while (*p.p && *p.p != ']' && *p.p != '\n') p.p++;
            if (*p.p == ']') p.p++;

            // Create new table
            toml_table_t *new_tab = new_table();
            new_tab->name = section;

            // Add to root
            toml_table_t **pp = &root->next;
            while (*pp) pp = &(*pp)->next;
            *pp = new_tab;
            current = new_tab;
            continue;
        }

        // Parse key=value
        char *key = parse_key(&p);
        if (!key) break;

        skip_whitespace_and_comments(&p);
        if (*p.p != '=') {
            free(key);
            break;
        }
        p.p++; // skip =

        toml_datum_t val;
        if (parse_value(&p, &val) < 0) {
            free(key);
            continue; // Skip invalid values
        }

        // Store in current table
        entry *e = calloc(1, sizeof(entry));
        e->key = key;
        if (val.ok) {
            if (val.u.i || val.u.d) {  // Check which field was set
                // Heuristic: if integer part is valid and no decimal
                char *check = p.p;
                while (check > p.data && isspace((unsigned char)*check)) check--;
                // Actually just store based on what was parsed
                if (val.u.d != 0.0 || strchr(key, '.') != NULL) {
                    e->type = val.u.d ? ENTRY_DOUBLE : ENTRY_INT;
                    e->u.d = val.u.d;
                    e->u.i = val.u.i;
                } else {
                    e->type = ENTRY_INT;
                    e->u.i = val.u.i;
                }
            }
            if (val.u.b) {
                e->type = ENTRY_BOOL;
                e->u.b = val.u.b;
            }
        }

        entry **ep = &current->first;
        while (*ep) ep = &(*ep)->next;
        *ep = e;
    }

    return root;
}

toml_table_t *toml_parse_file(FILE *fp, char *errbuf, int errbufsz) {
    fseek(fp, 0, SEEK_END);
    long len = ftell(fp);
    fseek(fp, 0, SEEK_SET);

    char *buf = malloc(len + 1);
    if (!buf) return NULL;
    fread(buf, 1, len, fp);
    buf[len] = '\0';

    toml_table_t *t = toml_parse(buf, errbuf, errbufsz);
    // Keep buf alive (attached to parser) or free it?
    // For simplicity, don't free - memory leak but small
    return t;
}

void toml_free(toml_table_t *tab) {
    while (tab) {
        toml_table_t *next = tab->next;
        entry *e = tab->first;
        while (e) {
            entry *en = e->next;
            free(e->key);
            free(e);
            e = en;
        }
        free(tab->name);
        free(tab);
        tab = next;
    }
}

int toml_key_exists(toml_table_t *tab, const char *key) {
    for (entry *e = tab->first; e; e = e->next) {
        if (e->key && strcmp(e->key, key) == 0) return 1;
    }
    return 0;
}

const char *toml_key_in(toml_table_t *tab, int idx) {
    entry *e = tab->first;
    while (idx-- > 0 && e) e = e->next;
    return e ? e->key : NULL;
}

static entry *find_entry(toml_table_t *tab, const char *key) {
    for (entry *e = tab->first; e; e = e->next) {
        if (e->key && strcmp(e->key, key) == 0) return e;
    }
    return NULL;
}

toml_table_t *toml_table_in(toml_table_t *tab, const char *key) {
    entry *e = find_entry(tab, key);
    if (e && e->type == ENTRY_TABLE) {
        return e->u.tab;
    }
    return NULL;
}

toml_array_t *toml_array_in(toml_table_t *tab, const char *key) {
    (void)tab;
    (void)key;
    return NULL; // Not implemented
}

toml_datum_t toml_string_in(toml_table_t *tab, const char *key) {
    toml_datum_t d = {0};
    entry *e = find_entry(tab, key);
    if (e && e->type == ENTRY_STRING) {
        d.ok = 1;
        d.u.s = e->u.s;
    }
    return d;
}

toml_datum_t toml_int_in(toml_table_t *tab, const char *key) {
    toml_datum_t d = {0};
    entry *e = find_entry(tab, key);
    if (e) {
        if (e->type == ENTRY_INT) {
            d.ok = 1;
            d.u.i = e->u.i;
        } else if (e->type == ENTRY_DOUBLE) {
            d.ok = 1;
            d.u.i = (int64_t)e->u.d;
        }
    }
    return d;
}

toml_datum_t toml_double_in(toml_table_t *tab, const char *key) {
    toml_datum_t d = {0};
    entry *e = find_entry(tab, key);
    if (e) {
        if (e->type == ENTRY_DOUBLE) {
            d.ok = 1;
            d.u.d = e->u.d;
        } else if (e->type == ENTRY_INT) {
            d.ok = 1;
            d.u.d = (double)e->u.i;
        }
    }
    return d;
}

toml_datum_t toml_bool_in(toml_table_t *tab, const char *key) {
    toml_datum_t d = {0};
    entry *e = find_entry(tab, key);
    if (e && e->type == ENTRY_BOOL) {
        d.ok = 1;
        d.u.b = e->u.b;
    }
    return d;
}

toml_datum_t toml_int_at(toml_array_t *arr, int idx) {
    (void)arr;
    (void)idx;
    toml_datum_t d = {0};
    return d;
}

toml_datum_t toml_double_at(toml_array_t *arr, int idx) {
    (void)arr;
    (void)idx;
    toml_datum_t d = {0};
    return d;
}

/*
 * toml.h - Minimal TOML parser interface
 */

#ifndef TOML_H
#define TOML_H

#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

#ifdef __cplusplus
extern "C" {
#endif

/* Entry types for internal use */
typedef enum entry_type {
    ENTRY_TABLE,
    ENTRY_ARRAY,
    ENTRY_STRING,
    ENTRY_INT,
    ENTRY_DOUBLE,
    ENTRY_BOOL
} entry_type;

/* Forward declarations */
typedef struct toml_table toml_table_t;
typedef struct toml_array toml_array_t;

/* Entry structure */
typedef struct entry {
    struct entry *next;
    char *key;
    entry_type type;
    union {
        toml_table_t *tab;
        toml_array_t *arr;
        char *s;
        int64_t i;
        double d;
        int b;
    } u;
} entry;

/* Table structure */
struct toml_table {
    char *name;
    entry *first;
    entry *last;
    toml_table_t *next;
};

/* Array structure (minimal) */
struct toml_array {
    int nelem;
    void *data;
};

/* Datum for return values */
typedef struct {
    int ok;
    union {
        int64_t  i;
        double   d;
        int      b;
        char    *s;
    } u;
} toml_datum_t;

/* Parse functions */
toml_table_t *toml_parse(char *toml, char *errbuf, int errbufsz);
toml_table_t *toml_parse_file(FILE *fp, char *errbuf, int errbufsz);

/* Free function */
void toml_free(toml_table_t *tab);

/* Key operations */
int toml_key_exists(toml_table_t *tab, const char *key);
const char *toml_key_in(toml_table_t *tab, int keyidx);

/* Access by key */
toml_table_t *toml_table_in(toml_table_t *tab, const char *key);
toml_array_t *toml_array_in(toml_table_t *tab, const char *key);
toml_datum_t toml_string_in(toml_table_t *tab, const char *key);
toml_datum_t toml_int_in(toml_table_t *tab, const char *key);
toml_datum_t toml_double_in(toml_table_t *tab, const char *key);
toml_datum_t toml_bool_in(toml_table_t *tab, const char *key);

/* Array access (minimal implementation) */
toml_datum_t toml_int_at(toml_array_t *arr, int idx);
toml_datum_t toml_double_at(toml_array_t *arr, int idx);

#ifdef __cplusplus
}
#endif

#endif /* TOML_H */

/*
 * buildprl.c - Convert parallax TOML to binary PRL format
 * Replaces buildprl.py
 * 
 * Binary layout:
 * - num_strips (u8)
 * For each strip:
 *   - u0 (u8), v0 (u8)
 *   - width (u16 BE), height (u16 BE)
 *   - bg_index (u8)
 *   - single (u8)
 *   - scrollx (s32 BE - 20.12 fixed)
 *   - speedx (s32 BE - 20.12 fixed)
 *   - y0 (s16 BE)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <libgen.h>
#include "toml.h"
#include "psxtypes.h"

#define MAX_STRIPS 256

typedef struct {
    u8 u0;
    u8 v0;
    u16 width;
    u16 height;
    u8 bg_index;
    u8 single;
    s32 scrollx;  // 20.12 fixed point
    s32 speedx;   // 20.12 fixed point
    s16 y0;
} ParallaxStrip;

typedef struct {
    int num_strips;
    ParallaxStrip strips[MAX_STRIPS];
} ParallaxData;

static inline s32 float_to_fixed12(float f) {
    return (s32)(f * 4096.0f);
}

void print_usage(const char *prog) {
    fprintf(stderr, "Usage: %s <parallax.toml>\n", prog);
    fprintf(stderr, "Output: PRL.PRL in same directory as input\n");
}

const char* get_output_path(const char *input_path) {
    static char output_path[1024];
    char *copy = strdup(input_path);
    char *dir = dirname(copy);

    if (strlen(dir) > 0) {
        snprintf(output_path, sizeof(output_path), "%s/PRL.PRL", dir);
    } else {
        snprintf(output_path, sizeof(output_path), "PRL.PRL");
    }

    free(copy);
    return output_path;
}

int parse_parallax(const char *filename, ParallaxData *prl) {
    FILE *f = fopen(filename, "r");
    if (!f) {
        fprintf(stderr, "Error: cannot open %s\n", filename);
        return -1;
    }

    // Read entire file
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = malloc(size + 1);
    fread(buf, 1, size, f);
    buf[size] = '\0';
    fclose(f);

    char errbuf[256];
    toml_table_t *root = toml_parse(buf, errbuf, sizeof(errbuf));

    if (!root) {
        fprintf(stderr, "Error: TOML parse failed: %s\n", errbuf);
        free(buf);
        return -1;
    }

    // Iterate through all tables (each is a strip)
    int num_strips = 0;
    toml_table_t *tab = root->next;  // Skip root, get first section

    while (tab && num_strips < MAX_STRIPS) {
        ParallaxStrip *s = &prl->strips[num_strips];
        memset(s, 0, sizeof(ParallaxStrip));

        // Read values (use .ok to check if found)
        toml_datum_t u0 = toml_int_in(tab, "u0");
        toml_datum_t v0 = toml_int_in(tab, "v0");
        toml_datum_t width = toml_int_in(tab, "width");
        toml_datum_t height = toml_int_in(tab, "height");
        toml_datum_t y0 = toml_int_in(tab, "y0");
        toml_datum_t single = toml_bool_in(tab, "single");

        // Floats
        toml_datum_t scrollx = toml_double_in(tab, "scrollx");
        toml_datum_t speedx = toml_double_in(tab, "speedx");

        // Use defaults if not found
        s->u0 = u0.ok ? (u8)u0.u.i : 0;
        s->v0 = v0.ok ? (u8)v0.u.i : 0;
        s->width = width.ok ? (u16)width.u.i : 0;
        s->height = height.ok ? (u16)height.u.i : 0;
        s->y0 = y0.ok ? (s16)y0.u.i : 0;
        s->single = single.ok ? (single.u.b ? 1 : 0) : 0;

        // Floats default to 0
        s->scrollx = scrollx.ok ? float_to_fixed12((float)scrollx.u.d) : 0;
        s->speedx = speedx.ok ? float_to_fixed12((float)speedx.u.d) : 0;

        // Calculate bg_index from v0
        s->bg_index = (s->v0 >= 256) ? 1 : 0;

        printf("Strip %s: u0=%d v0=%d (%d:%d) %dx%d y0=%d scrollx=%d speedx=%d\n", 
               tab->name ? tab->name : "?", s->u0, s->v0, 
               s->bg_index, s->v0, s->width, s->height, s->y0,
               s->scrollx, s->speedx);

        tab = tab->next;
        num_strips++;
    }

    prl->num_strips = num_strips;

    toml_free(root);
    free(buf);

    printf("Total strips: %d\n", num_strips);
    return 0;
}

int write_parallax(const char *filename, const ParallaxData *prl) {
    FILE *f = fopen(filename, "wb");
    if (!f) {
        fprintf(stderr, "Error: cannot create %s\n", filename);
        return -1;
    }

    // Write number of strips
    write_u8(f, (u8)prl->num_strips);

    // Write each strip
    for (int i = 0; i < prl->num_strips; i++) {
        const ParallaxStrip *s = &prl->strips[i];
        write_u8(f, s->u0);
        write_u8(f, s->v0);
        write_u16_be(f, s->width);
        write_u16_be(f, s->height);
        write_u8(f, s->bg_index);
        write_u8(f, s->single);
        write_s32_be(f, s->scrollx);
        write_s32_be(f, s->speedx);
        write_s16_be(f, s->y0);
    }

    fclose(f);
    printf("Created %s (%d bytes)\n", filename, (int)(1 + prl->num_strips * 18));
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        print_usage(argv[0]);
        return 1;
    }

    const char *input = argv[1];
    const char *output = get_output_path(input);

    ParallaxData prl = {0};

    if (parse_parallax(input, &prl) != 0) {
        return 1;
    }

    if (write_parallax(output, &prl) != 0) {
        return 1;
    }

    return 0;
}

