/*
 * chunkmapper.c - Generate .tmx from Aseprite JSON tile mapping
 * Replaces chunkmapper.py
 * 
 * Input: JSON from Aseprite export_tilemap_psx
 * Output: tilemap128.tmx (in current directory)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "cJSON.h"

#define CHUNK_SIZE 8
#define CHUNKS_PER_ROW 4

typedef struct {
    int *tiles;  // CHUNK_SIZE * CHUNK_SIZE tiles
    int width;
    int height;
} Chunk;

void print_usage(const char *prog) {
    fprintf(stderr, "Usage: %s <input.json>\n", prog);
    fprintf(stderr, "Output: tilemap128.tmx (in current directory)\n");
}

// Parse JSON and extract chunks
int parse_chunks(const char *filename, Chunk **chunks, int *num_chunks) {
    FILE *f = fopen(filename, "r");
    if (!f) {
        fprintf(stderr, "Error: cannot open %s\n", filename);
        return -1;
    }

    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = malloc(size + 1);
    fread(buf, 1, size, f);
    buf[size] = '\0';
    fclose(f);

    cJSON *root = cJSON_Parse(buf);
    free(buf);

    if (!root) {
        fprintf(stderr, "Error: JSON parse failed\n");
        return -1;
    }

    // Get layers[0].cels
    cJSON *layers = cJSON_GetObjectItem(root, "layers");
    if (!cJSON_IsArray(layers) || cJSON_GetArraySize(layers) == 0) {
        fprintf(stderr, "Error: no layers found\n");
        cJSON_Delete(root);
        return -1;
    }

    cJSON *layer0 = cJSON_GetArrayItem(layers, 0);
    cJSON *cels = cJSON_GetObjectItem(layer0, "cels");
    if (!cJSON_IsArray(cels)) {
        fprintf(stderr, "Error: no cels found\n");
        cJSON_Delete(root);
        return -1;
    }

    int count = cJSON_GetArraySize(cels);
    *chunks = calloc(count + 1, sizeof(Chunk));  // +1 for empty first chunk

    // First chunk is always empty
    (*chunks)[0].width = CHUNK_SIZE;
    (*chunks)[0].height = CHUNK_SIZE;
    (*chunks)[0].tiles = calloc(CHUNK_SIZE * CHUNK_SIZE, sizeof(int));
    memset((*chunks)[0].tiles, 0, CHUNK_SIZE * CHUNK_SIZE * sizeof(int));

    // Parse each cel as a chunk
    for (int i = 0; i < count; i++) {
        cJSON *cel = cJSON_GetArrayItem(cels, i);
        cJSON *tilemap = cJSON_GetObjectItem(cel, "tilemap");
        cJSON *tiles = cJSON_GetObjectItem(tilemap, "tiles");
        cJSON *bounds = cJSON_GetObjectItem(cel, "bounds");

        int cols = cJSON_GetObjectItem(tilemap, "width")->valueint;
        int rows = cJSON_GetObjectItem(tilemap, "height")->valueint;

        // Validate - must be at least 8x8
        if (cols < CHUNK_SIZE || rows < CHUNK_SIZE) {
            fprintf(stderr, "ERROR: chunk %d is smaller than %dx%d\n", i, CHUNK_SIZE, CHUNK_SIZE);
            cJSON_Delete(root);
            return -1;
        }

        Chunk *chunk = &(*chunks)[i + 1];
        chunk->width = cols;
        chunk->height = rows;
        chunk->tiles = malloc(cols * rows * sizeof(int));

        // Copy tiles (add 1 to each value, as per Python version)
        int tile_count = cJSON_GetArraySize(tiles);
        for (int j = 0; j < tile_count; j++) {
            cJSON *t = cJSON_GetArrayItem(tiles, j);
            chunk->tiles[j] = t->valueint + 1;
        }
    }

    *num_chunks = count + 1;
    cJSON_Delete(root);
    return 0;
}

// Add padding chunks to make total divisible by 4
int pad_chunks(Chunk **chunks, int *num_chunks) {
    int needed = CHUNKS_PER_ROW - (*num_chunks % CHUNKS_PER_ROW);
    if (needed == CHUNKS_PER_ROW) return 0;  // Already divisible

    int new_count = *num_chunks + needed;
    *chunks = realloc(*chunks, new_count * sizeof(Chunk));

    for (int i = *num_chunks; i < new_count; i++) {
        (*chunks)[i].width = CHUNK_SIZE;
        (*chunks)[i].height = CHUNK_SIZE;
        (*chunks)[i].tiles = calloc(CHUNK_SIZE * CHUNK_SIZE, sizeof(int));
        memset((*chunks)[i].tiles, 0, CHUNK_SIZE * CHUNK_SIZE * sizeof(int));
    }

    *num_chunks = new_count;
    return needed;
}

// Write TMX file
void write_tmx(const char *filename, Chunk *chunks, int num_chunks) {
    FILE *f = fopen(filename, "w");
    if (!f) {
        fprintf(stderr, "Error: cannot create %s\n", filename);
        return;
    }

    // Calculate dimensions
    int num_chunk_rows = num_chunks / CHUNKS_PER_ROW;
    int width_tiles = CHUNKS_PER_ROW * CHUNK_SIZE;  // 32
    int height_tiles = num_chunk_rows * CHUNK_SIZE;

    // Header
    fprintf(f, "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n");
    fprintf(f, "<map version=\"1.10\" tiledversion=\"1.11.2\" "
               "orientation=\"orthogonal\" renderorder=\"right-down\" "
               "width=\"%d\" height=\"%d\" tilewidth=\"16\" tileheight=\"16\" "
               "infinite=\"0\" nextlayerid=\"2\" nextobjectid=\"1\">\n",
               width_tiles, height_tiles);
    fprintf(f, " <tileset firstgid=\"1\" source=\"tiles16.tsx\" />\n");
    fprintf(f, " <layer id=\"1\" name=\"solid\" width=\"%d\" height=\"%d\">\n",
               width_tiles, height_tiles);
    fprintf(f, "  <data encoding=\"csv\">\n");

    // Group chunks into rows of 4
    for (int row = 0; row < num_chunk_rows; row++) {
        Chunk *row_chunks[CHUNKS_PER_ROW];
        for (int c = 0; c < CHUNKS_PER_ROW; c++) {
            row_chunks[c] = &chunks[row * CHUNKS_PER_ROW + c];
        }

        // For each row within the chunks
        for (int y = 0; y < CHUNK_SIZE; y++) {
            int first = 1;
            // Concatenate 4 chunks horizontally
            for (int c = 0; c < CHUNKS_PER_ROW; c++) {
                Chunk *chunk = row_chunks[c];
                for (int x = 0; x < CHUNK_SIZE; x++) {
                    if (!first) fprintf(f, ",");
                    first = 0;
                    fprintf(f, "%d", chunk->tiles[y * CHUNK_SIZE + x]);
                }
            }
            fprintf(f, "\n");
        }
    }

    fprintf(f, "  </data>\n");
    fprintf(f, " </layer>\n");
    fprintf(f, "</map>\n");

    fclose(f);
    printf("Created %s (%dx%d tiles)\n", filename, width_tiles, height_tiles);
}

void free_chunks(Chunk *chunks, int num_chunks) {
    for (int i = 0; i < num_chunks; i++) {
        free(chunks[i].tiles);
    }
    free(chunks);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        print_usage(argv[0]);
        return 1;
    }

    const char *input = argv[1];

    Chunk *chunks = NULL;
    int num_chunks = 0;

    if (parse_chunks(input, &chunks, &num_chunks) != 0) {
        return 1;
    }

    printf("Parsed %d chunks\n", num_chunks);

    // Pad to make divisible by 4
    int padded = pad_chunks(&chunks, &num_chunks);
    if (padded > 0) {
        printf("Added %d padding chunks\n", padded);
    }

    // Generate TMX
    write_tmx("tilemap128.tmx", chunks, num_chunks);

    free_chunks(chunks, num_chunks);

    return 0;
}

/*
 * cookcollision.c - Cook 16x16 tile collision from Tiled tile data
 * Replaces cookcollision.py
 * 
 * Replaces shapely with custom ray casting for point-in-polygon
 * Calculates height masks and angles for 4 directions per tile
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <stdbool.h>
#include "cJSON.h"
#include "psxtypes.h"

#define TILE_SIZE 16
#define MAX_VERTICES 16

typedef struct {
    float x, y;
} Vec2;

typedef struct {
    int id;
    Vec2 vertices[MAX_VERTICES];
    int num_vertices;
    int predef_floor_angle;
    int predef_ceil_angle;
    int predef_rwall_angle;
    int predef_lwall_angle;
} TileCollision;

typedef enum {
    DIR_DOWN = 0,
    DIR_UP = 1,
    DIR_LEFT = 2,
    DIR_RIGHT = 3
} Direction;

typedef struct {
    int heights[16];  // Height mask (0-15)
    s32 angle;      // PSX angle (0-4096, 20.12 fixed)
} CollisionMask;

typedef struct {
    CollisionMask floor;
    CollisionMask ceiling;
    CollisionMask rwall;
    CollisionMask lwall;
} TileMasks;

void print_usage(const char *prog) {
    fprintf(stderr, "Usage: %s <input.json> <output.COL>\n", prog);
}

// Point in polygon using ray casting algorithm
// Returns 1 if point is inside, 0 if outside
int point_in_polygon(float px, float py, Vec2 *verts, int n) {
    if (n < 3) return 0;

    bool inside = false;
    for (int i = 0, j = n - 1; i < n; j = i++) {
        float xi = verts[i].x, yi = verts[i].y;
        float xj = verts[j].x, yj = verts[j].y;

        if (((yi > py) != (yj > py)) && 
            (px < (xj - xi) * (py - yi) / (yj - yi) + xi)) {
            inside = !inside;
        }
    }
    return inside ? 1 : 0;
}

// Normalize vector
void normalize_vec(float *vx, float *vy) {
    float len = sqrtf(*vx * *vx + *vy * *vy);
    if (len > 0.0001f) {
        *vx /= len;
        *vy /= len;
    }
}

// Convert angle in radians to PSX format (0-4096 = 0-360 degrees)
// PSX uses 20.12 fixed point: 1.0 = 4096
s32 to_psx_angle(float radians) {
    float degrees = radians * 180.0f / M_PI;
    // Normalize to 0-360
    while (degrees < 0) degrees += 360.0f;
    while (degrees >= 360.0f) degrees -= 360.0f;

    float ratio = degrees / 360.0f;
    return (s32)(ratio * 4096.0f);
}

// Get height mask by line casting
void get_height_mask(CollisionMask *mask, Direction dir, Vec2 *verts, int n, 
                     int predef_angle, bool has_predef) {
    int heightmask[16];
    int last_pos = 0;

    for (int pos = 0; pos < 16; pos++) {
        bool found = false;
        for (int h = 15; h >= 1; h--) {
            float x, y;
            switch (dir) {
                case DIR_DOWN:
                    x = pos;
                    y = TILE_SIZE - h;
                    break;
                case DIR_UP:
                    x = TILE_SIZE - 1 - pos;
                    y = h;
                    break;
                case DIR_LEFT:
                    x = h;
                    y = pos;
                    break;
                case DIR_RIGHT:
                    x = TILE_SIZE - h;
                    y = TILE_SIZE - 1 - pos;
                    break;
                default:
                    x = y = 0;
            }

            if (point_in_polygon(x, y, verts, n)) {
                found = true;
                heightmask[pos] = h;
                if (pos > 0 && heightmask[pos - 1] != h) {
                    last_pos = pos;
                }
                break;
            }
        }
        if (!found) {
            heightmask[pos] = 0;
        }
    }

    // Copy to mask
    memcpy(mask->heights, heightmask, sizeof(heightmask));

    // Use predefined angle or calculate
    if (has_predef) {
        mask->angle = predef_angle;
        return;
    }

    // Calculate angle from height mask
    int delta = heightmask[0] - heightmask[last_pos];
    float vx, vy;
    float dx, dy;  // Direction vector

    switch (dir) {
        case DIR_DOWN:
            vx = TILE_SIZE;
            vy = delta;
            dx = 1; dy = 0;
            break;
        case DIR_UP:
            vx = -TILE_SIZE;
            vy = -delta;
            dx = -1; dy = 0;
            break;
        case DIR_LEFT:
            vx = -delta;
            vy = TILE_SIZE;
            dx = 0; dy = 1;
            break;
        case DIR_RIGHT:
            vx = delta;
            vy = -TILE_SIZE;
            dx = 0; dy = -1;
            break;
        default:
            vx = vy = dx = dy = 0;
    }

    normalize_vec(&vx, &vy);
    float angle = atan2f(dy, dx) - atan2f(vy, vx);
    if (angle < 0) angle += 2 * M_PI;

    mask->angle = to_psx_angle(angle);
}

// Parse JSON collision data
int parse_collisions(const char *filename, TileCollision **tiles, int *num_tiles) {
    FILE *f = fopen(filename, "r");
    if (!f) {
        fprintf(stderr, "Error: cannot open %s\n", filename);
        return -1;
    }

    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = malloc(size + 1);
    fread(buf, 1, size, f);
    buf[size] = '\0';
    fclose(f);

    cJSON *root = cJSON_Parse(buf);
    free(buf);

    if (!root) {
        fprintf(stderr, "Error: JSON parse failed\n");
        return -1;
    }

    cJSON *tiles_arr = cJSON_GetObjectItem(root, "tiles");
    if (!cJSON_IsArray(tiles_arr)) {
        fprintf(stderr, "Error: no tiles array\n");
        cJSON_Delete(root);
        return -1;
    }

    int count = cJSON_GetArraySize(tiles_arr);
    *tiles = calloc(count, sizeof(TileCollision));
    int valid_count = 0;

    for (int i = 0; i < count; i++) {
        cJSON *tile = cJSON_GetArrayItem(tiles_arr, i);
        TileCollision *tc = &(*tiles)[valid_count];

        tc->id = cJSON_GetObjectItem(tile, "id")->valueint;

        cJSON *objgrp = cJSON_GetObjectItem(tile, "objectgroup");
        if (!objgrp) continue;

        cJSON *objs = cJSON_GetObjectItem(objgrp, "objects");
        if (!cJSON_IsArray(objs) || cJSON_GetArraySize(objs) == 0) continue;

        cJSON *o = cJSON_GetArrayItem(objs, 0);

        // Parse properties for predefined angles
        cJSON *props = cJSON_GetObjectItem(o, "properties");
        if (cJSON_IsArray(props)) {
            int nprops = cJSON_GetArraySize(props);
            for (int j = 0; j < nprops; j++) {
                cJSON *prop = cJSON_GetArrayItem(props, j);
                const char *name = cJSON_GetObjectItem(prop, "name")->valuestring;
                const char *val = cJSON_GetObjectItem(prop, "value")->valuestring;
                int ang = (int)strtol(val, NULL, 16);  // Hex value

                if (strcmp(name, "floor_angle") == 0) tc->predef_floor_angle = ang;
                else if (strcmp(name, "ceil_angle") == 0) tc->predef_ceil_angle = ang;
                else if (strcmp(name, "rwall_angle") == 0) tc->predef_rwall_angle = ang;
                else if (strcmp(name, "lwall_angle") == 0) tc->predef_lwall_angle = ang;
            }
        }

        // Get base position
        float ox = cJSON_GetObjectItem(o, "x")->valuedouble;
        float oy = cJSON_GetObjectItem(o, "y")->valuedouble;

        // Get polygon or rect
        cJSON *poly = cJSON_GetObjectItem(o, "polygon");
        if (poly && cJSON_IsArray(poly)) {
            int nvert = cJSON_GetArraySize(poly);
            if (nvert > MAX_VERTICES) nvert = MAX_VERTICES;
            tc->num_vertices = nvert;

            for (int j = 0; j < nvert; j++) {
                cJSON *v = cJSON_GetArrayItem(poly, j);
                tc->vertices[j].x = roundf(cJSON_GetObjectItem(v, "x")->valuedouble + ox);
                tc->vertices[j].y = roundf(cJSON_GetObjectItem(v, "y")->valuedouble + oy);
            }
        } else {
            // Rectangle
            float w = roundf(cJSON_GetObjectItem(o, "width")->valuedouble);
            float h = roundf(cJSON_GetObjectItem(o, "height")->valuedouble);
            tc->num_vertices = 4;
            tc->vertices[0] = (Vec2){ox, oy};
            tc->vertices[1] = (Vec2){ox + w, oy};
            tc->vertices[2] = (Vec2){ox + w, oy + h};
            tc->vertices[3] = (Vec2){ox, oy + h};
        }

        valid_count++;
    }

    *num_tiles = valid_count;
    cJSON_Delete(root);
    return 0;
}

// Calculate masks for all tiles
void process_masks(TileCollision *tiles, int num_tiles, TileMasks **masks) {
    *masks = calloc(num_tiles, sizeof(TileMasks));

    for (int i = 0; i < num_tiles; i++) {
        TileCollision *tc = &tiles[i];
        TileMasks *tm = &(*masks)[i];

        get_height_mask(&tm->floor, DIR_DOWN, tc->vertices, tc->num_vertices,
                        tc->predef_floor_angle, tc->predef_floor_angle != 0);
        get_height_mask(&tm->ceiling, DIR_UP, tc->vertices, tc->num_vertices,
                        tc->predef_ceil_angle, tc->predef_ceil_angle != 0);
        get_height_mask(&tm->rwall, DIR_RIGHT, tc->vertices, tc->num_vertices,
                        tc->predef_rwall_angle, tc->predef_rwall_angle != 0);
        get_height_mask(&tm->lwall, DIR_LEFT, tc->vertices, tc->num_vertices,
                        tc->predef_lwall_angle, tc->predef_lwall_angle != 0);
    }
}

// Write mask data (16 nibbles -> 8 bytes)
void write_mask_data(FILE *f, int *heights) {
    for (int i = 0; i < 16; i += 2) {
        u8 a = (heights[i] & 0x0F) << 4;
        u8 b = heights[i + 1] & 0x0F;
        write_u8(f, a | b);
    }
}

// Write output file
void write_collision_file(const char *filename, TileCollision *tiles, 
                          TileMasks *masks, int num_tiles) {
    FILE *f = fopen(filename, "wb");
    if (!f) {
        fprintf(stderr, "Error: cannot create %s\n", filename);
        return;
    }

    // Number of tiles
    write_u16_be(f, (u16)num_tiles);

    for (int i = 0; i < num_tiles; i++) {
        // Tile ID
        write_u16_be(f, (u16)tiles[i].id);

        // Floor
        write_s32_be(f, masks[i].floor.angle);
        write_mask_data(f, masks[i].floor.heights);

        // Right wall
        write_s32_be(f, masks[i].rwall.angle);
        write_mask_data(f, masks[i].rwall.heights);

        // Ceiling
        write_s32_be(f, masks[i].ceiling.angle);
        write_mask_data(f, masks[i].ceiling.heights);

        // Left wall
        write_s32_be(f, masks[i].lwall.angle);
        write_mask_data(f, masks[i].lwall.heights);
    }

    fclose(f);
    printf("Created %s (%d tiles)\n", filename, num_tiles);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        print_usage(argv[0]);
        return 1;
    }

    const char *input = argv[1];
    const char *output = argv[2];

    TileCollision *tiles = NULL;
    int num_tiles = 0;

    if (parse_collisions(input, &tiles, &num_tiles) != 0) {
        return 1;
    }

    printf("Parsed %d collision tiles\n", num_tiles);

    TileMasks *masks = NULL;
    process_masks(tiles, num_tiles, &masks);

    write_collision_file(output, tiles, masks, num_tiles);

    free(tiles);
    free(masks);

    return 0;
}

