/*
 * cookcollision.c - Cook 16x16 tile collision from Tiled tile data
 * Replaces cookcollision.py - uses yyjson for fast JSON parsing
 * 
 * Build: gcc -O2 -I../lib/yyjson -I../include \
 *        cookcollision.c ../lib/yyjson/yyjson.c ../lib/minilib.c -lm -o cookcollision
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <stdbool.h>
#include <stdint.h>
#include "yyjson.h"
#include "psxtypes.h"

#define TILE_SIZE 16
#define MAX_VERTICES 16

typedef struct {
    float x, y;
} Vec2;

typedef struct {
    int id;
    Vec2 vertices[MAX_VERTICES];
    int num_vertices;
    int predef_floor_angle;
    int predef_ceil_angle;
    int predef_rwall_angle;
    int predef_lwall_angle;
} TileCollision;

typedef enum {
    DIR_DOWN = 0,
    DIR_UP = 1,
    DIR_LEFT = 2,
    DIR_RIGHT = 3
} Direction;

typedef struct {
    int heights[16];
    s32 angle;
} CollisionMask;

typedef struct {
    CollisionMask floor;
    CollisionMask ceiling;
    CollisionMask rwall;
    CollisionMask lwall;
} TileMasks;

void print_usage(const char *prog) {
    fprintf(stderr, "Usage: %s <input.json> <output.COL>\n", prog);
}

// Point in polygon using ray casting
int point_in_polygon(float px, float py, Vec2 *verts, int n) {
    if (n < 3) return 0;

    bool inside = false;
    for (int i = 0, j = n - 1; i < n; j = i++) {
        float xi = verts[i].x, yi = verts[i].y;
        float xj = verts[j].x, yj = verts[j].y;

        if (((yi > py) != (yj > py) && 
            (px < (xj - xi) * (py - yi) / (yj - yi) + xi) {
            inside = !inside;
        }
    }
    return inside ? 1 : 0;
}

void normalize_vec(float *vx, float *vy) {
    float len = sqrtf(*vx * *vx + *vy * *vy);
    if (len > 0.0001f) {
        *vx /= len;
        *vy /= len;
    }
}

s32 to_psx_angle(float radians) {
    float degrees = radians * 180.0f / M_PI;
    while (degrees < 0) degrees += 360.0f;
    while (degrees >= 360.0f) degrees -= 360.0f;

    float ratio = degrees / 360.0f;
    return (s32)(ratio * 4096.0f);
}

void get_height_mask(CollisionMask *mask, Direction dir, Vec2 *verts, int n, 
                     int predef_angle, bool has_predef) {
    int heightmask[16];
    int last_pos = 0;

    for (int pos = 0; pos < 16; pos++) {
        bool found = false;
        for (int h = 15; h >= 1; h--) {
            float x, y;
            switch (dir) {
                case DIR_DOWN:    x = pos; y = TILE_SIZE - h; break;
                case DIR_UP:      x = TILE_SIZE - 1 - pos; y = h; break;
                case DIR_LEFT:    x = h; y = pos; break;
                case DIR_RIGHT:   x = TILE_SIZE - h; y = TILE_SIZE - 1 - pos; break;
                default: x = y = 0;
            }

            if (point_in_polygon(x, y, verts, n) {
                found = true;
                heightmask[pos] = h;
                if (pos > 0 && heightmask[pos - 1] != h) {
                    last_pos = pos;
                }
                break;
            }
        }
        if (!found) heightmask[pos] = 0;
    }

    memcpy(mask->heights, heightmask, sizeof(heightmask);

    if (has_predef) {
        mask->angle = predef_angle;
        return;
    }

    int delta = heightmask[0] - heightmask[last_pos];
    float vx = 0, vy = 0, dx = 0, dy = 0;

    switch (dir) {
        case DIR_DOWN:  vx = TILE_SIZE; vy = delta; dx = 1; dy = 0; break;
        case DIR_UP:    vx = -TILE_SIZE; vy = -delta; dx = -1; dy = 0; break;
        case DIR_LEFT:  vx = -delta; vy = TILE_SIZE; dx = 0; dy = 1; break;
        case DIR_RIGHT: vx = delta; vy = -TILE_SIZE; dx = 0; dy = -1; break;
    }

    normalize_vec(&vx, &vy);
    float angle = atan2f(dy, dx) - atan2f(vy, vx);
    if (angle < 0) angle += 2 * M_PI;

    mask->angle = to_psx_angle(angle);
}

int parse_collisions(const char *filename, TileCollision **tiles, int *num_tiles) {
    // Read file
    FILE *f = fopen(filename, "r");
    if (!f) {
        fprintf(stderr, "Error: cannot open %s\n", filename);
        return -1;
    }

    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = malloc(size + 1);
    fread(buf, 1, size, f);
    buf[size] = '\0';
    fclose(f);

    // Parse JSON
    yyjson_doc *doc = yyjson_read(buf, size, 0);
    free(buf);

    if (!doc) {
        fprintf(stderr, "Error: JSON parse failed\n");
        return -1;
    }

    yyjson_val *root = yyjson_doc_get_root(doc);
    yyjson_val *tiles_arr = yyjson_obj_get(root, "tiles");

    if (!tiles_arr || !yyjson_is_arr(tiles_arr) {
        fprintf(stderr, "Error: no tiles array\n");
        yyjson_doc_free(doc);
        return -1;
    }

    size_t count = yyjson_arr_size(tiles_arr);
    *tiles = calloc(count, sizeof(TileCollision);
    int valid_count = 0;

    size_t idx, max;
    yyjson_val *tile;
    yyjson_arr_foreach(tiles_arr, idx, max, tile) {
        TileCollision *tc = &(*tiles)[valid_count];
        memset(tc, 0, sizeof(TileCollision);

        // Get id
        yyjson_val *id = yyjson_obj_get(tile, "id");
        tc->id = yyjson_get_int(id);

        // Get objectgroup
        yyjson_val *objgrp = yyjson_obj_get(tile, "objectgroup");
        if (!objgrp) continue;

        yyjson_val *objs = yyjson_obj_get(objgrp, "objects");
        if (!objs || !yyjson_is_arr(objs) || yyjson_arr_size(objs) == 0) continue;

        // Process first object
        yyjson_val *o = yyjson_arr_get_first(objs);

        // Parse properties
        yyjson_val *props = yyjson_obj_get(o, "properties");
        if (yyjson_is_arr(props) {
            size_t pidx, pmax;
            yyjson_val *prop;
            yyjson_arr_foreach(props, pidx, pmax, prop) {
                yyjson_val *name = yyjson_obj_get(prop, "name");
                yyjson_val *val = yyjson_obj_get(prop, "value");

                if (!name || !val) continue;

                const char *n = yyjson_get_str(name);
                const char *v = yyjson_get_str(val);
                if (!n || !v) continue;

                int ang = (int)strtol(v, NULL, 16);

                if (strcmp(n, "floor_angle") == 0) tc->predef_floor_angle = ang;
                else if (strcmp(n, "ceil_angle") == 0) tc->predef_ceil_angle = ang;
                else if (strcmp(n, "rwall_angle") == 0) tc->predef_rwall_angle = ang;
                else if (strcmp(n, "lwall_angle") == 0) tc->predef_lwall_angle = ang;
            }
        }

        // Get position
        float ox = (float)yyjson_get_num(yyjson_obj_get(o, "x");
        float oy = (float)yyjson_get_num(yyjson_obj_get(o, "y");

        yyjson_val *poly = yyjson_obj_get(o, "polygon");
        if (poly && yyjson_is_arr(poly) {
            size_t nvert = yyjson_arr_size(poly);
            if (nvert > MAX_VERTICES) nvert = MAX_VERTICES;
            tc->num_vertices = (int)nvert;

            yyjson_val *v;
            yyjson_arr_iter viter;
            yyjson_arr_iter_init(poly, &viter);
            int vidx = 0;
            while ((v = yyjson_arr_iter_next(&viter) && vidx < MAX_VERTICES) {
                tc->vertices[vidx].x = (float)yyjson_get_num(yyjson_obj_get(v, "x") + ox);
                tc->vertices[vidx].y = (float)yyjson_get_num(yyjson_obj_get(v, "y") + oy);
                vidx++;
            }
        } else {
            // Rectangle
            float w = (float)yyjson_get_num(yyjson_obj_get(o, "width";

            float h = (float)yyjson_get_num(yyjson_obj_get(o, "height";

            tc->num_vertices = 4;
            tc->vertices[0] = (Vec2){ox, oy};
            tc->vertices[1] = (Vec2){ox + w, oy};
            tc->vertices[2] = (Vec2){ox + w, oy + h};
            tc->vertices[3] = (Vec2){ox, oy + h};
        }

        valid_count++;
    }

    *num_tiles = valid_count;
    yyjson_doc_free(doc);
    return 0;
}

void process_masks(TileCollision *tiles, int num_tiles, TileMasks **masks) {
    *masks = calloc(num_tiles, sizeof(TileMasks);

    for (int i = 0; i < num_tiles; i++) {
        TileCollision *tc = &tiles[i];
        TileMasks *tm = &(*masks)[i];

        get_height_mask(&tm->floor, DIR_DOWN, tc->vertices, tc->num_vertices,
                        tc->predef_floor_angle, tc->predef_floor_angle != 0);
        get_height_mask(&tm->ceiling, DIR_UP, tc->vertices, tc->num_vertices,
                        tc->predef_ceil_angle, tc->predef_ceil_angle != 0);
        get_height_mask(&tm->rwall, DIR_RIGHT, tc->vertices, tc->num_vertices,
                        tc->predef_rwall_angle, tc->predef_rwall_angle != 0);
        get_height_mask(&tm->lwall, DIR_LEFT, tc->vertices, tc->num_vertices,
                        tc->predef_lwall_angle, tc->predef_lwall_angle != 0);
    }
}

